    }

    .evidence-panel {
      position: sticky;
      top: 28px;
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface);
      box-shadow: var(--shadow);
    }

    .evidence-panel small {
      display: block;
      margin-bottom: 16px;
      color: var(--muted);
      font: 10px var(--mono);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .evidence-panel h3 {
      margin-bottom: 9px;
      font-family: var(--display);
      font-size: 24px;
      font-weight: 500;
    }

    .evidence-panel > p {
      margin-bottom: 22px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .evidence-list {
      display: grid;
      gap: 10px;
    }

    .evidence-item {
      padding: 13px 0;
      border-top: 1px solid var(--border);
    }

    .evidence-item strong {
      display: block;
      margin-bottom: 5px;
      font-size: 12px;
    }

    .evidence-item span {
      color: var(--muted);
      font-size: 11px;
      line-height: 1.5;
    }

    .control-intro {
      margin-bottom: 24px;
      padding: 19px 22px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface);
      display: flex;
      justify-content: space-between;
      gap: 24px;
    }

    .control-intro strong {
      display: block;
      margin-bottom: 5px;
      font-size: 13px;
    }

    .control-intro p {
      margin: 0;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.55;
    }

    .control-table {
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface);
      overflow: hidden;
    }

    .control-row {
      min-height: 104px;
      padding: 19px 22px;
      border-bottom: 1px solid var(--border);
      display: grid;
      grid-template-columns: minmax(230px, 1.2fr) repeat(3, minmax(130px, 0.7fr)) 76px;
      gap: 16px;
      align-items: center;
    }

    .control-row:last-child { border-bottom: 0; }

    .control-head {
      min-height: 54px;
      color: var(--muted);
      font: 10px var(--mono);
      text-transform: uppercase;
      letter-spacing: 0.07em;
    }

    .app-name {
      display: flex;
      align-items: center;
      gap: 13px;
    }

    .app-icon {
      width: 42px;
      height: 42px;
      border: 1px solid var(--border);
      border-radius: 10px;
      display: grid;
      place-items: center;
      background: var(--bg);
      font-family: var(--display);
      font-size: 17px;
    }

    .app-name strong {
      display: block;
      margin-bottom: 4px;
      font-size: 13px;
    }

    .app-name span {
      color: var(--muted);
      font-size: 11px;
    }

    .permission {
      color: var(--muted);
      font-size: 12px;
    }

    .permission strong {
      display: block;
      margin-bottom: 4px;
      color: var(--fg);
      font-size: 12px;
    }

    .switch {
      width: 50px;
      height: 28px;
      padding: 3px;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: oklch(0.91 0.01 255);
      display: flex;
      align-items: center;
      transition: background 160ms var(--ease), border-color 160ms var(--ease);
    }

    .switch::after {
      content: "";
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: var(--surface);
      box-shadow: 0 1px 4px oklch(0.2 0.03 258 / 0.2);
      transition: transform 180ms var(--ease);
    }

    .switch[aria-pressed="true"] {
      border-color: var(--fg);
      background: var(--fg);
    }

    .switch[aria-pressed="true"]::after {
      transform: translateX(20px);
    }

    .drawer-backdrop {
      position: fixed;
      inset: 0;
      z-index: 10;
      padding: 28px;
      background: oklch(0.14 0.025 258 / 0.42);
      display: grid;
      justify-items: end;
      opacity: 0;
      visibility: hidden;
      transition: opacity 140ms var(--ease), visibility 140ms;
    }

    .drawer-backdrop.open {
      opacity: 1;
      visibility: visible;
    }

    .drawer {
      width: min(580px, 100%);
      height: 100%;
      padding: 28px;
      border: 1px solid oklch(1 0 0 / 0.2);
      border-radius: 18px;
      background: var(--surface);
      box-shadow: 0 30px 100px oklch(0.1 0.02 258 / 0.22);
      overflow-y: auto;
      transform: translateX(20px);
      transition: transform 210ms var(--ease);
    }

    .drawer-backdrop.open .drawer { transform: translateX(0); }

    .drawer-head {
      margin-bottom: 34px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .drawer-progress {
      color: var(--muted);
      font: 11px var(--mono);
    }

    .close-button {
      width: 44px;
      height: 44px;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: transparent;
      font-size: 20px;
    }

    .close-button:hover { background: oklch(0.94 0.01 255); }

    .review-label {
      margin-bottom: 14px;
      color: var(--warning);
      font: 600 10px var(--mono);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .review-title {
      margin-bottom: 8px;
      font-family: var(--display);
      font-size: 34px;
      font-weight: 500;
      line-height: 1.12;
      letter-spacing: -0.035em;
    }

    .review-subtitle {
      margin-bottom: 26px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .diff-block {
      margin-bottom: 22px;
      border: 1px solid var(--border);
      border-radius: 14px;
      overflow: hidden;
    }

    .diff-side {
      padding: 20px;
      background: var(--surface);
    }

    .diff-side + .diff-side { border-top: 1px solid var(--border); }

    .diff-side.after { background: var(--accent-soft); }

    .diff-side small {
      display: block;
      margin-bottom: 8px;
      color: var(--muted);
      font: 10px var(--mono);
      text-transform: uppercase;
    }

    .diff-side p {
      margin: 0;
      font-family: var(--display);
      font-size: 20px;
      line-height: 1.4;
    }

    .reason-list {
      margin-bottom: 25px;
      padding: 18px 20px;
      border-left: 2px solid var(--border);
    }

    .reason-list strong {
      display: block;
      margin-bottom: 10px;
      font-size: 12px;
    }

    .reason-list ul {
      margin: 0;
      padding-left: 18px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.8;
    }

    .more-evidence {
      max-height: 0;
      overflow: hidden;
      opacity: 0;
      transition: max-height 200ms var(--ease), opacity 160ms var(--ease);
    }

    .more-evidence.open {
      max-height: 180px;
      opacity: 1;
    }

    .drawer-actions {
      display: flex;
      align-items: center;
      gap: 9px;
      flex-wrap: wrap;
    }

    .toast {
      position: fixed;
      left: 50%;
      bottom: 28px;
      z-index: 20;
      min-width: 260px;
      padding: 13px 17px;
      border-radius: 10px;
      background: var(--fg);
      color: var(--surface);
      font-size: 12px;
      text-align: center;
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translate(-50%, 12px);
      pointer-events: none;
      transition: opacity 170ms var(--ease), transform 170ms var(--ease);
    }

    .toast.show {
      opacity: 1;
      transform: translate(-50%, 0);
    }

    @media (max-width: 1080px) {
      .summary-grid { grid-template-columns: repeat(2, 1fr); }
      .summary-item:nth-child(2) { border-right: 0; }
      .summary-item:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
      .me-layout { grid-template-columns: 1fr; }
      .evidence-panel { position: static; }
      .control-row {
        grid-template-columns: minmax(220px, 1fr) repeat(3, 110px) 60px;
      }
    }

    @media (max-width: 820px) {
      .app-shell { display: block; }
      .sidebar {
        position: static;
        width: 100%;
        height: auto;
        padding: 14px 18px;
        border-right: 0;
        border-bottom: 1px solid var(--border);
        flex-direction: row;
        align-items: center;
        gap: 20px;
      }
      .nav {
        margin-left: auto;
        grid-auto-flow: column;
      }
      .nav-button { min-height: 44px; }
      .nav-button span:first-child { display: none; }
      .sidebar-note { display: none; }
      .main { padding: 16px 20px 48px; }
      .page-head { padding-top: 30px; }
      h1 { font-size: 44px; }
      .feed-card { grid-template-columns: 1fr; gap: 10px; }
      .feed-action { text-align: left; }
      .control-table { overflow-x: auto; }
      .control-row { min-width: 820px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
