      const storedScreen = localStorage.getItem("memory-lens-screen") || "home";
      let reviewStep = 0;
      let remainingDecisions = 2;
      let toastTimer;

      const reviewItems = [
        {
          label: "오래된 것으로 추정",
          title: "Flutter에 대한 이해를 업데이트할까요?",
