          <h2 class="review-title" id="reviewTitle" data-od-id="review-heading">${item.title}</h2>
          <p class="review-subtitle">${item.subtitle}</p>
          <div class="diff-block" data-od-id="memory-diff">
            <div class="diff-side">
              <small>Before</small>
              <p>${item.before}</p>
            </div>
            <div class="diff-side after">
              <small>After</small>
              <p>${item.after}</p>
            </div>
          </div>
          <div class="reason-list">
            <strong>이렇게 판단한 근거 ${item.reasons.length}개</strong>
            <ul>${item.reasons.map(reason => `<li>${reason}</li>`).join("")}</ul>
          </div>
          <div class="more-evidence" id="moreEvidence">
            <div class="reason-list">
              <strong>변경 원칙</strong>
              <ul><li>기존 기억은 삭제하지 않고 변경 이력에 보관합니다.</li><li>새 이해는 관련 AI에만 공유됩니다.</li></ul>
            </div>
          </div>
          <div class="drawer-actions">
            <button class="primary-button" id="acceptReview" data-od-id="accept-memory-change">변경 승인</button>
            <button class="secondary-button" id="keepReview" data-od-id="keep-old-memory">기존 이해 유지</button>
            <button class="text-button" id="moreReview" data-od-id="show-more-evidence">더 알아보기</button>
          </div>
        `;

        document.getElementById("acceptReview").addEventListener("click", () => completeReview("변경을 승인했습니다."));
        document.getElementById("keepReview").addEventListener("click", () => completeReview("기존 이해를 유지합니다."));
        document.getElementById("moreReview").addEventListener("click", event => {
          document.getElementById("moreEvidence").classList.toggle("open");
          event.currentTarget.textContent = document.getElementById("moreEvidence").classList.contains("open") ? "접기" : "더 알아보기";
        });
      }

      function completeReview(message) {
        remainingDecisions -= 1;
        document.getElementById("navDecisionCount").textContent = remainingDecisions;
        document.getElementById("decisionNumber").textContent = remainingDecisions;
        toast(message);

        if (reviewStep < reviewItems.length - 1) {
          reviewStep += 1;
          renderReview();
          document.querySelector(".drawer").scrollTop = 0;
        } else {
          closeReview();
          document.getElementById("decisionCallout").innerHTML = `
            <div class="decision-copy">
              <div class="decision-number">✓</div>
              <div><strong>이번 주 검토를 마쳤습니다</strong><span>나머지 변화는 자동으로 관리됩니다.</span></div>
            </div>
          `;
          document.getElementById("navDecisionCount").remove();
        }
      }

      function openReview() {
        reviewStep = Math.min(reviewStep, reviewItems.length - 1);
        renderReview();
        const backdrop = document.getElementById("reviewBackdrop");
        backdrop.classList.add("open");
        backdrop.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
        setTimeout(() => document.getElementById("closeReview").focus(), 10);
      }

      function closeReview() {
        const backdrop = document.getElementById("reviewBackdrop");
        backdrop.classList.remove("open");
        backdrop.setAttribute("aria-hidden", "true");
        document.body.style.overflow = "";
        document.getElementById("startReview")?.focus();
      }

      document.getElementById("startReview").addEventListener("click", openReview);
      document.getElementById("closeReview").addEventListener("click", closeReview);
      document.getElementById("reviewBackdrop").addEventListener("click", event => {
        if (event.target.id === "reviewBackdrop") closeReview();
      });
      document.addEventListener("keydown", event => {
        if (event.key === "Escape" && document.getElementById("reviewBackdrop").classList.contains("open")) closeReview();
      });

      function updateEvidence(key) {
        const data = evidenceData[key];
        document.getElementById("evidenceTitle").textContent = data.title;
        document.getElementById("evidenceSummary").textContent = data.summary;
        document.getElementById("evidenceList").innerHTML = data.items.map(item =>
          `<div class="evidence-item"><strong>${item[0]}</strong><span>${item[1]}</span></div>`
        ).join("");
      }

      document.querySelectorAll(".model-card").forEach(button => {
        button.addEventListener("click", () => {
          document.querySelectorAll(".model-card").forEach(item => item.classList.remove("active"));
          button.classList.add("active");
          updateEvidence(button.dataset.model);
        });
      });
      updateEvidence("work");

      document.querySelectorAll(".switch").forEach(button => {
        button.addEventListener("click", () => {
          const next = button.getAttribute("aria-pressed") !== "true";
          button.setAttribute("aria-pressed", String(next));
          toast(next ? "AI 연결을 다시 허용했습니다." : "AI의 메모리 접근을 중지했습니다.");
        });
      });

      document.getElementById("pauseSharing").addEventListener("click", event => {
        const switches = [...document.querySelectorAll(".switch")];
        const shouldPause = switches.some(item => item.getAttribute("aria-pressed") === "true");
        switches.forEach(item => item.setAttribute("aria-pressed", shouldPause ? "false" : "true"));
        event.currentTarget.textContent = shouldPause ? "전체 공유 다시 시작" : "전체 공유 일시 중지";
        toast(shouldPause ? "모든 AI의 메모리 접근을 일시 중지했습니다." : "AI별 공유 범위를 다시 적용했습니다.");
      });
    })();
  </script>
