    .orbit-stage::after {
      content: "";
      position: absolute;
      width: 420px;
      height: 420px;
      border-radius: 50%;
      background: radial-gradient(circle, oklch(0.66 0.19 245 / 0.13), transparent 68%);
      filter: blur(18px);
