    .orbit-ring.two {
      width: 410px;
      height: 410px;
      border-style: dashed;
      border-color: oklch(0.88 0.04 255 / 0.11);
      animation: ringRotate 44s linear infinite;
    }

    .orbit-ring.three {
      width: 520px;
      height: 520px;
      border-color: oklch(0.88 0.04 255 / 0.07);
    }

    @keyframes ringBreath {
      from { transform: scale(0.97); opacity: 0.65; }
      to { transform: scale(1.03); opacity: 1; }
    }

    @keyframes ringRotate {
      to { transform: rotate(360deg); }
    }

    .memory-core {
      position: relative;
      width: 150px;
      height: 150px;
      border-radius: 50%;
      background:
        radial-gradient(circle at 36% 30%, oklch(0.96 0.08 215), transparent 15%),
        radial-gradient(circle at 68% 67%, oklch(0.58 0.24 305), transparent 31%),
        radial-gradient(circle at 34% 68%, oklch(0.65 0.2 225), transparent 36%),
        oklch(0.3 0.08 260);
      box-shadow:
        0 0 30px oklch(0.67 0.2 250 / 0.36),
        0 0 90px oklch(0.58 0.19 285 / 0.22),
        inset -16px -18px 30px oklch(0.12 0.05 265 / 0.4);
      animation: coreFloat 5.5s var(--ease) infinite alternate;
    }

    .memory-core::before,
    .memory-core::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      inset: -12px;
      border: 1px solid oklch(0.92 0.07 250 / 0.22);
      animation: corePulse 3.6s var(--ease) infinite;
    }

    .memory-core::after {
      inset: -28px;
      animation-delay: 1.2s;
    }

    @keyframes coreFloat {
      from { transform: translateY(-5px) rotate(-3deg); }
      to { transform: translateY(8px) rotate(4deg); }
    }

    @keyframes corePulse {
