    }

    .review-label {
      margin-bottom: 14px;
      color: var(--warning);
      font: 650 10px var(--mono);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .review-title {
      margin-bottom: 8px;
      font: 650 31px/1.13 var(--display);
      letter-spacing: -0.055em;
    }

    .review-subtitle {
      margin-bottom: 26px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .diff-block {
      margin-bottom: 22px;
      border: 1px solid var(--border);
      border-radius: 14px;
      overflow: hidden;
    }

    .diff-side {
      padding: 20px;
      background: var(--surface);
    }

    .diff-side + .diff-side { border-top: 1px solid var(--border); }
    .diff-side.after { background: var(--accent-soft); }

    .diff-side small {
      display: block;
      margin-bottom: 8px;
      color: var(--muted);
      font: 10px var(--mono);
      text-transform: uppercase;
    }

    .diff-side p {
      margin: 0;
      font: 570 18px/1.5 var(--display);
      letter-spacing: -0.025em;
    }

    .reason-list {
      margin-bottom: 25px;
      padding: 18px 20px;
      border-left: 2px solid var(--border);
    }

    .reason-list strong {
      display: block;
      margin-bottom: 10px;
      font-size: 12px;
    }

    .reason-list ul {
      margin: 0;
      padding-left: 18px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.8;
    }

    .more-evidence {
      max-height: 0;
      overflow: hidden;
      opacity: 0;
      transition: max-height 200ms var(--ease), opacity 160ms var(--ease);
    }

    .more-evidence.open {
      max-height: 180px;
      opacity: 1;
    }

    .drawer-actions {
      display: flex;
      align-items: center;
      gap: 9px;
      flex-wrap: wrap;
    }

    .chat-drawer {
      padding: 0;
      overflow: hidden;
      display: grid;
      grid-template-rows: auto 1fr auto;
    }

    .chat-head {
      min-height: 82px;
      padding: 18px 22px;
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .chat-head strong {
      display: block;
      margin-bottom: 4px;
      font-size: 14px;
    }

    .chat-head span {
      color: var(--muted);
      font-size: 11px;
    }

    .chat-log {
      min-height: 0;
      padding: 26px 22px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .chat-message {
      max-width: 84%;
      padding: 13px 15px;
      border-radius: 14px;
      font-size: 13px;
      line-height: 1.58;
    }

    .chat-message.ai {
      align-self: flex-start;
      border: 1px solid var(--border);
      border-bottom-left-radius: 4px;
      background: var(--surface);
    }

    .chat-message.user {
      align-self: flex-end;
      border-bottom-right-radius: 4px;
      background: var(--fg);
      color: white;
    }

    .chat-source {
      margin-top: 8px;
      color: var(--muted);
      font: 10px var(--mono);
    }

    .chat-composer {
      padding: 14px;
      border-top: 1px solid var(--border);
      background: var(--surface);
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
    }

    .chat-input {
      min-height: 46px;
      min-width: 0;
      padding: 0 14px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--bg);
      color: var(--fg);
    }

    .chat-input::placeholder { color: var(--muted); }

    .toast {
      position: fixed;
      left: 50%;
      bottom: 28px;
      z-index: 20;
      min-width: 260px;
      padding: 13px 17px;
      border-radius: 10px;
      background: var(--fg);
      color: var(--surface);
      text-align: center;
      font-size: 12px;
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translate(-50%, 12px);
      pointer-events: none;
      transition: opacity 170ms var(--ease), transform 170ms var(--ease);
    }

    .toast.show {
      opacity: 1;
      transform: translate(-50%, 0);
    }

    @media (max-width: 1160px) {
      .memory-hero { min-height: 700px; }
      .hero-copy { width: 58%; padding-left: 42px; }
      .orbit-stage { right: -95px; width: 57%; }
      .summary-grid { grid-template-columns: repeat(2, 1fr); }
      .summary-item:nth-child(2) { border-right: 0; }
      .summary-item:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
      .me-layout { grid-template-columns: 1fr; }
      .evidence-panel { position: static; }
      .control-row { grid-template-columns: minmax(220px, 1fr) repeat(3, 110px) 60px; }
    }

    @media (max-width: 900px) {
      .app-shell { display: block; }
      .sidebar {
        position: static;
        width: 100%;
        height: auto;
        padding: 14px 18px;
        border-right: 0;
        border-bottom: 1px solid var(--border);
        flex-direction: row;
        align-items: center;
        gap: 20px;
      }
      .nav { margin-left: auto; grid-auto-flow: column; }
      .nav-button { min-height: 44px; }
      .nav-button span:first-child { display: none; }
      .sidebar-note { display: none; }
      .main { padding: 16px 20px 48px; }
      .memory-hero { min-height: 900px; }
      .hero-copy {
        width: 100%;
        min-height: 390px;
        padding: 52px 32px 30px;
      }
      .hero-copy h1 { font-size: 50px; }
      .orbit-stage {
        top: 350px;
        right: 0;
        width: 100%;
        height: 450px;
        transform: scale(0.86);
      }
      .hero-report-strip {
        grid-template-columns: repeat(3, 1fr);
        bottom: 15px;
      }
      .report-intro { display: none; }
      .feed-card { grid-template-columns: 1fr; gap: 10px; }
      .feed-action { text-align: left; }
      .control-table { overflow-x: auto; }
      .control-row { min-width: 820px; }
    }

    @media (max-width: 620px) {
      .main { padding-inline: 12px; }
      .memory-hero { min-height: 820px; border-radius: 18px; }
      .hero-copy { padding-inline: 24px; }
      .hero-copy h1 { font-size: 42px; }
      .orbit-stage {
        top: 350px;
        transform: scale(0.7);
      }
      .hero-report-strip { padding: 0 12px; }
      .report-stat { padding-left: 12px; }
      .summary-grid { grid-template-columns: 1fr; }
      .summary-item {
        min-height: 96px;
        border-right: 0;
        border-bottom: 1px solid var(--border);
      }
      .decision-callout {
        align-items: flex-start;
        flex-direction: column;
      }
      .model-card { grid-template-columns: 86px 1fr 20px; gap: 10px; }
      .overlay { padding: 10px; }
      .report-row { grid-template-columns: 78px 1fr; }
      .report-row b { grid-column: 2; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <div class="app-shell">
    <aside class="sidebar" data-od-id="primary-navigation">
      <div class="brand" data-od-id="product-brand">
        <div class="brand-mark" aria-hidden="true">ML</div>
        <div class="brand-name">Memory Lens</div>
      </div>

      <nav class="nav" aria-label="주요 화면">
        <button class="nav-button active" data-screen="home" data-od-id="nav-home">
          <span>Home</span>
          <span class="nav-count" id="navDecisionCount">2</span>
        </button>
        <button class="nav-button" data-screen="me" data-od-id="nav-me"><span>Me</span></button>
        <button class="nav-button" data-screen="control" data-od-id="nav-control"><span>Control</span></button>
      </nav>

      <div class="sidebar-note" data-od-id="automation-status">
        <strong>자동 관리 중</strong>
        <p>확신할 수 있는 기억은 조용히 정리하고, 판단이 필요한 변화만 보여드립니다.</p>
      </div>
    </aside>

    <main class="main" id="content">
      <header class="topbar" data-od-id="top-status">
        <div class="status-pill"><span class="status-dot" aria-hidden="true"></span>마지막 동기화 · 방금 전</div>
        <div class="avatar" aria-label="사용자 프로필">IH</div>
      </header>

      <section class="screen active" id="home" data-od-id="home-screen">
        <div class="memory-hero" data-od-id="memory-orbit-hero">
          <div class="hero-copy">
            <div class="hero-eyebrow">Weekly memory intelligence</div>
            <h1 data-od-id="home-heading">이번 주, 당신에 대한 이해가 달라졌습니다.</h1>
            <p>37개의 변화를 분석했고 대부분은 조용히 정리했습니다. 지금은 AI가 발견한 흐름을 리포트로 보거나, 당신의 기억과 직접 대화할 수 있습니다.</p>
            <div class="hero-actions">
              <button class="hero-primary" id="openReport" data-od-id="open-memory-report">리포트 열기</button>
              <button class="hero-secondary" id="openChat" data-od-id="open-memory-chat">메모리와 대화</button>
            </div>
          </div>

          <div class="orbit-stage" aria-label="사용자의 기억이 중심 모델 주위를 움직이는 시각화">
            <div class="orbit-ring one"></div>
            <div class="orbit-ring two"></div>
            <div class="orbit-ring three"></div>

            <div class="memory-core" data-od-id="memory-core">
              <div class="core-label">
                <strong>94%</strong>
                <span>자동 정리됨</span>
              </div>
            </div>

            <div class="orbit-track">
              <div class="orbit-memory"><button class="memory-chip">디자인 완성도를 중시함</button></div>
              <div class="orbit-memory"><button class="memory-chip">AI 코딩 도구를 적극 사용</button></div>
              <div class="orbit-memory"><button class="memory-chip">해커톤에서는 속도 우선</button></div>
              <div class="orbit-memory"><button class="memory-chip">Flutter 사용 빈도 감소</button></div>
              <div class="orbit-memory"><button class="memory-chip">정보량이 절제된 UI 선호</button></div>
              <div class="orbit-memory"><button class="memory-chip">여러 프로젝트를 동시 탐색</button></div>
            </div>
          </div>

          <div class="hero-report-strip" data-od-id="hero-report-summary">
            <div class="report-intro">
              <strong>2026년 8월 2주 차</strong>
              <span>개인 메모리 인텔리전스 리포트</span>
            </div>
            <div class="report-stat"><strong>37</strong><span>발견한 변화</span></div>
            <div class="report-stat"><strong>2</strong><span>판단 필요</span></div>
            <div class="report-stat"><strong>18</strong><span>자동 보관</span></div>
          </div>
        </div>

        <div class="summary-grid" data-od-id="weekly-summary">
          <article class="summary-item" data-od-id="summary-strengthened"><span class="summary-label">강화된 이해</span><span class="summary-value">12</span></article>
          <article class="summary-item" data-od-id="summary-outdated"><span class="summary-label">오래된 것으로 추정</span><span class="summary-value">4</span></article>
          <article class="summary-item" data-od-id="summary-contextualized"><span class="summary-label">맥락을 찾은 충돌</span><span class="summary-value">3</span></article>
          <article class="summary-item" data-od-id="summary-archived"><span class="summary-label">자동 보관</span><span class="summary-value">18</span></article>
        </div>

        <div class="decision-callout" id="decisionCallout" data-od-id="decision-callout">
          <div class="decision-copy">
            <div class="decision-number" id="decisionNumber">2</div>
            <div><strong>당신의 판단이 필요한 변화가 있습니다</strong><span>예상 소요 시간 47초</span></div>
          </div>
          <button class="primary-button" id="startReview" data-od-id="start-review">검토 시작</button>
        </div>

        <div class="section-head">
          <div>
            <h2 data-od-id="feed-heading">무엇이 달라졌나요</h2>
            <p>아무것도 하지 않으면 신뢰도에 따라 자동으로 반영됩니다.</p>
          </div>
          <div class="filter-row" role="group" aria-label="변화 유형 필터">
            <button class="filter active" data-filter="all" data-od-id="filter-all">전체</button>
            <button class="filter" data-filter="changed" data-od-id="filter-changed">변화</button>
            <button class="filter" data-filter="fading" data-od-id="filter-fading">소멸</button>
            <button class="filter" data-filter="context" data-od-id="filter-context">맥락</button>
          </div>
        </div>

        <div class="feed" data-od-id="memory-change-feed">
          <article class="feed-card" data-type="changed" data-od-id="feed-card-framework">
            <div class="feed-type changed">Changed</div>
            <div class="feed-content">
              <h3>이제 Flutter를 가장 먼저 선택하지 않을 수 있습니다.</h3>
              <p>지난 90일간 시작한 새 프로젝트 6개 중 Flutter로 시작한 프로젝트는 1개였습니다.</p>
              <div class="evidence-line"><span>근거 14개</span><span>확신도 높음</span></div>
            </div>
            <div class="feed-action"><button class="text-button feed-action-button">변화 보기</button></div>
          </article>

          <article class="feed-card" data-type="fading" data-od-id="feed-card-student-collective">
            <div class="feed-type fading">Fading</div>
            <div class="feed-content">
              <h3>“OpenAI Student Collective 지원 준비 중”</h3>
              <p>특정 이벤트에 묶인 기억으로, 현재 일반적인 답변에는 더 이상 필요하지 않은 것으로 보입니다.</p>
              <div class="evidence-line"><span>자동 보관 예정</span><span>3일 후</span></div>
            </div>
            <div class="feed-action"><button class="text-button feed-action-button">계속 유지</button></div>
          </article>

          <article class="feed-card" data-type="changed" data-od-id="feed-card-preference-merge">
            <div class="feed-type merged">Merged</div>
            <div class="feed-content">
              <h3>두 디자인 취향을 하나의 선호로 정리했습니다.</h3>
              <p>“정보량이 많은 UI를 싫어함”과 “여백이 많은 디자인을 선호함”을 더 정확한 하나의 문장으로 병합했습니다.</p>
              <div class="evidence-line"><span>중복 기억 2개</span><span>자동 반영됨</span></div>
            </div>
            <div class="feed-action"><button class="text-button feed-action-button">결과 보기</button></div>
          </article>

          <article class="feed-card" data-type="context" data-od-id="feed-card-speed-quality">
            <div class="feed-type context">Context</div>
            <div class="feed-content">
              <h3>속도와 완성도는 충돌하지 않았습니다.</h3>
              <p>해커톤에서는 실행 속도를, 소비자 제품에서는 디자인 완성도를 우선하는 조건부 패턴을 발견했습니다.</p>
              <div class="evidence-line"><span>근거 23개</span><span>새 맥락 생성</span></div>
            </div>
            <div class="feed-action"><button class="text-button feed-action-button">근거 확인</button></div>
          </article>
        </div>
      </section>

      <section class="screen" id="me" data-od-id="me-screen">
        <div class="page-head">
          <div class="eyebrow">Memory Lens</div>
          <h1 data-od-id="me-heading">AI는 나를 어떻게 이해하고 있나요?</h1>
          <p>수백 개의 개별 기억을 사람이 읽을 수 있는 모델로 압축했습니다. 문장을 선택하면 그 판단의 근거가 열립니다.</p>
        </div>

        <div class="me-layout">
          <div class="model-list" data-od-id="personal-model-list">
            <button class="model-card active" data-model="work" data-od-id="model-work">
              <span class="model-category">Work</span>
              <span class="model-statement">빠른 실행을 중요하게 생각하지만, 소비자 제품에서는 디자인 완성도를 쉽게 타협하지 않는다.</span>
              <span class="model-arrow" aria-hidden="true">→</span>
            </button>
            <button class="model-card" data-model="coding" data-od-id="model-coding">
              <span class="model-category">Coding</span>
              <span class="model-statement">AI 코딩 도구를 적극적으로 사용하며, 특정 프레임워크에는 이전보다 덜 고착되어 있다.</span>
              <span class="model-arrow" aria-hidden="true">→</span>
            </button>
            <button class="model-card" data-model="projects" data-od-id="model-projects">
              <span class="model-category">Projects</span>
              <span class="model-statement">여러 프로젝트를 동시에 탐색하고, 가능성이 낮으면 빠르게 폐기하거나 전환하는 편이다.</span>
              <span class="model-arrow" aria-hidden="true">→</span>
            </button>
            <button class="model-card" data-model="preferences" data-od-id="model-preferences">
              <span class="model-category">Preferences</span>
              <span class="model-statement">정보량이 절제되고 시각적 위계가 강한 인터페이스를 선호한다.</span>
              <span class="model-arrow" aria-hidden="true">→</span>
            </button>
            <button class="model-card" data-model="current" data-od-id="model-current-life">
              <span class="model-category">Current life</span>
              <span class="model-statement">최근 해커톤과 AI 제품 실험에 집중하고 있다.</span>
              <span class="model-arrow" aria-hidden="true">→</span>
            </button>
          </div>

          <aside class="evidence-panel" data-od-id="model-evidence-panel" aria-live="polite">
            <small>왜 그렇게 생각하나요</small>
            <h3 id="evidenceTitle">속도와 완성도의 조건</h3>
            <p id="evidenceSummary">서로 모순되어 보이던 두 선호가 작업 맥락에 따라 달라진다는 패턴을 발견했습니다.</p>
            <div class="evidence-list" id="evidenceList"></div>
          </aside>
        </div>
      </section>

      <section class="screen" id="control" data-od-id="control-screen">
        <div class="page-head">
          <div class="eyebrow">공유 범위</div>
          <h1 data-od-id="control-heading">누가 무엇을 알 수 있나요?</h1>
          <p>기억을 하나씩 공개하지 않고, AI마다 필요한 이해의 범위를 결정합니다. 변경 내용은 다음 대화부터 적용됩니다.</p>
        </div>

        <div class="control-intro" data-od-id="control-summary">
          <div>
            <strong>최소 공유 원칙이 적용 중입니다</strong>
            <p>새 AI는 기본적으로 일반 선호만 볼 수 있으며, 업무·현재 상황은 별도 승인이 필요합니다.</p>
          </div>
          <button class="secondary-button" id="pauseSharing" data-od-id="pause-sharing">전체 공유 일시 중지</button>
        </div>

        <div class="control-table" data-od-id="ai-access-table">
          <div class="control-row control-head" aria-hidden="true">
            <div>연결된 AI</div><div>업무 방식</div><div>개인 선호</div><div>현재 상황</div><div>연결</div>
          </div>

          <div class="control-row" data-od-id="access-chatgpt">
            <div class="app-name"><div class="app-icon">C</div><div><strong>ChatGPT</strong><span>마지막 사용 · 오늘</span></div></div>
            <div class="permission"><strong>전체 맥락</strong>조건부 선호 포함</div>
            <div class="permission"><strong>전체 맥락</strong>디자인·도구</div>
            <div class="permission"><strong>제한됨</strong>30일 이내만</div>
            <button class="switch" aria-label="ChatGPT 연결" aria-pressed="true"></button>
          </div>

          <div class="control-row" data-od-id="access-[REDACTED_MODEL]">
            <div class="app-name"><div class="app-icon">A</div><div><strong>[REDACTED_MODEL]</strong><span>마지막 사용 · 어제</span></div></div>
            <div class="permission"><strong>전체 맥락</strong>프로젝트 방식</div>
            <div class="permission"><strong>기본 정보</strong>응답 선호만</div>
            <div class="permission"><strong>공유 안 함</strong>비공개</div>
            <button class="switch" aria-label="[REDACTED_MODEL] 연결" aria-pressed="true"></button>
          </div>

          <div class="control-row" data-od-id="access-work-ai">
            <div class="app-name"><div class="app-icon">W</div><div><strong>Work AI</strong><span>조직에서 관리</span></div></div>
            <div class="permission"><strong>업무 정보만</strong>개인 프로젝트 제외</div>
            <div class="permission"><strong>공유 안 함</strong>비공개</div>
            <div class="permission"><strong>공유 안 함</strong>비공개</div>
            <button class="switch" aria-label="Work AI 연결" aria-pressed="true"></button>
          </div>

          <div class="control-row" data-od-id="access-coding-ai">
            <div class="app-name"><div class="app-icon">K</div><div><strong>Coding AI</strong><span>마지막 사용 · 2시간 전</span></div></div>
            <div class="permission"><strong>코딩 맥락</strong>언어·도구 선호</div>
            <div class="permission"><strong>기본 정보</strong>출력 형식만</div>
            <div class="permission"><strong>공유 안 함</strong>비공개</div>
            <button class="switch" aria-label="Coding AI 연결" aria-pressed="true"></button>
          </div>
        </div>
      </section>
    </main>
  </div>

  <div class="overlay" id="reportOverlay" aria-hidden="true">
    <section class="dialog" role="dialog" aria-modal="true" aria-labelledby="reportTitle" data-od-id="weekly-memory-report">
      <div class="dialog-head">
        <h2 id="reportTitle">이번 주 메모리 리포트</h2>
        <button class="close-button" data-close="reportOverlay" aria-label="리포트 닫기">×</button>
      </div>
      <p class="report-lead">AI가 당신을 이해하는 방식은 더 유연해졌습니다. 도구에 대한 고정된 선호는 약해졌고, 상황에 따라 속도와 완성도를 조절하는 패턴은 더 강해졌습니다.</p>
      <article class="report-highlight" data-od-id="report-main-insight">
        <small>가장 큰 변화</small>
        <h3>“특정 프레임워크를 선호함”에서 “문제에 맞는 도구를 선택함”으로</h3>
        <p>최근 프로젝트 선택 14건을 바탕으로 기존 Flutter 중심 기억을 확장할 준비가 되었습니다.</p>
      </article>
      <div class="report-list">
        <div class="report-row"><span>강화됨</span><strong>제품 유형에 따라 속도와 완성도의 우선순위를 조절함</strong><b>+12</b></div>
        <div class="report-row"><span>약화됨</span><strong>Flutter를 항상 첫 번째 선택으로 사용함</strong><b>−4</b></div>
        <div class="report-row"><span>정리됨</span><strong>기한이 지난 이벤트성 정보와 중복 취향</strong><b>18</b></div>
      </div>
      <button class="primary-button" id="reviewFromReport" data-od-id="review-from-report">판단이 필요한 2개 검토</button>
    </section>
  </div>

  <div class="overlay align-right" id="reviewBackdrop" aria-hidden="true">
    <aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="reviewTitle" data-od-id="memory-review-drawer">
      <div class="drawer-head">
        <span class="drawer-progress" id="reviewProgress">판단 1 / 2</span>
        <button class="close-button" data-close="reviewBackdrop" aria-label="검토 닫기">×</button>
      </div>
      <div id="reviewContent"></div>
    </aside>
  </div>

  <div class="overlay align-right" id="chatOverlay" aria-hidden="true">
    <aside class="drawer chat-drawer" role="dialog" aria-modal="true" aria-labelledby="chatTitle" data-od-id="memory-chat">
      <header class="chat-head">
        <div><strong id="chatTitle">내 메모리와 대화</strong><span>답변은 저장된 근거만 사용합니다</span></div>
        <button class="close-button" data-close="chatOverlay" aria-label="대화 닫기">×</button>
      </header>
      <div class="chat-log" id="chatLog" aria-live="polite">
        <div class="chat-message ai">
          이번 주 리포트에서 가장 궁금한 점을 물어보세요. 제가 당신을 어떻게 이해하고 있는지 근거와 함께 설명할게요.
          <div class="chat-source">Memory Lens · 근거 기반 응답</div>
        </div>
        <div class="chat-message user">내가 정말 Flutter를 덜 선호한다고 생각해?</div>
        <div class="chat-message ai">
          “싫어한다”기보다는 첫 선택으로 고정하지 않는다고 이해하고 있어요. 최근 새 프로젝트 6개 중 Flutter는 1개였고, Swift와 웹 탐색은 13회 있었습니다.
          <div class="chat-source">관련 기억 14개 · 최근 90일</div>
        </div>
      </div>
      <form class="chat-composer" id="chatForm">
        <input class="chat-input" id="chatInput" aria-label="메모리에 관해 질문하기" placeholder="내가 왜 그렇게 보이는지 물어보세요">
        <button class="primary-button" type="submit" data-od-id="send-memory-chat">보내기</button>
      </form>
    </aside>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite"></div>

  <script>
    (() => {
      const screens = [...document.querySelectorAll(".screen")];
      const navButtons = [...document.querySelectorAll(".nav-button")];
      const storedScreen = localStorage.getItem("memory-lens-screen") || "home";
      let reviewStep = 0;
      let remainingDecisions = 2;
      let toastTimer;

      const reviewItems = [
        {
          label: "오래된 것으로 추정",
          title: "Flutter에 대한 이해를 업데이트할까요?",
          subtitle: "최근 행동이 기존 기억과 달라졌지만, 의도적인 변화인지 확인이 필요합니다.",
          before: "Flutter를 주 개발 프레임워크로 선호함",
          after: "모바일 개발 경험은 Flutter가 가장 많지만 최근에는 Swift와 웹 기반 개발도 자주 사용함",
          reasons: ["최근 90일 새 프로젝트 6개 중 Flutter는 1개", "Swift 관련 탐색 8회", "웹 기반 프로토타입 제작 5회"]
        },
        {
          label: "맥락이 필요한 충돌",
          title: "두 선호를 조건부 기억으로 바꿀까요?",
          subtitle: "둘 중 하나를 지우는 대신, 각각이 적용되는 상황을 발견했습니다.",
          before: "빠르게 MVP를 만드는 것을 선호함 ↔ 디자인 완성도를 매우 중요하게 생각함",
          after: "해커톤에서는 속도를 우선하고, 소비자 제품에서는 디자인 완성도를 우선함",
          reasons: ["해커톤 대화에서 실행 속도 11회 강조", "소비자 제품 리뷰에서 시각 완성도 9회 강조", "상황별 선택이 최근 4개월간 일관됨"]
        }
      ];

      const evidenceData = {
        work: {
          title: "속도와 완성도의 조건",
          summary: "서로 모순되어 보이던 두 선호가 작업 맥락에 따라 달라진다는 패턴을 발견했습니다.",
          items: [["해커톤", "짧은 시간 안에 작동하는 결과를 우선한 대화 11건"], ["소비자 제품", "시각적 마감과 경험 품질을 강조한 대화 9건"], ["최근 확인", "3일 전 · 제품 디자인 논의"]]
        },
        coding: {
          title: "프레임워크보다 문제 적합성",
          summary: "Flutter 경험은 여전히 강하지만 최근 선택은 제품 요구와 배포 환경에 따라 달라지고 있습니다.",
          items: [["Flutter", "최근 90일 새 프로젝트 1건"], ["Swift·웹", "동일 기간 탐색 및 구현 13건"], ["최근 확인", "어제 · 데스크탑 프로토타입 논의"]]
        },
        projects: {
          title: "넓게 탐색하고 빠르게 전환",
          summary: "초기에는 여러 가능성을 비교하고, 신호가 약한 방향은 유지 비용을 키우기 전에 전환합니다.",
          items: [["동시 탐색", "최근 프로젝트 아이디어 7개"], ["방향 전환", "초기 검증 후 범위를 줄인 사례 4개"], ["최근 확인", "5일 전 · MVP 범위 결정"]]
        },
        preferences: {
          title: "절제된 정보와 강한 위계",
          summary: "단순히 여백이 많은 화면보다, 중요도에 따라 정보가 명확히 압축된 인터페이스를 선호합니다.",
          items: [["반복 표현", "정보 밀도에 대한 피드백 19건"], ["선호 패턴", "하나의 명확한 주 행동과 강한 제목 위계"], ["최근 확인", "오늘 · Memory Lens 설계"]]
        },
        current: {
          title: "현재의 관심사",
          summary: "시간에 민감한 상태로 취급하며, 활동 신호가 줄어들면 자동으로 약화합니다.",
          items: [["해커톤", "최근 30일 관련 활동 12건"], ["AI 제품", "아이디어·프로토타입 대화 18건"], ["자동 만료", "활동이 45일 없으면 재검토"]]
        }
      };

      function showScreen(id) {
        screens.forEach(screen => screen.classList.toggle("active", screen.id === id));
        navButtons.forEach(button => button.classList.toggle("active", button.dataset.screen === id));
        localStorage.setItem("memory-lens-screen", id);
      }

      navButtons.forEach(button => button.addEventListener("click", () => showScreen(button.dataset.screen)));
      showScreen(storedScreen);

      function openOverlay(id) {
        const overlay = document.getElementById(id);
        overlay.classList.add("open");
        overlay.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
        setTimeout(() => overlay.querySelector("button, input")?.focus(), 20);
      }

      function closeOverlay(id) {
        const overlay = document.getElementById(id);
        overlay.classList.remove("open");
        overlay.setAttribute("aria-hidden", "true");
        if (!document.querySelector(".overlay.open")) document.body.style.overflow = "";
      }

      document.querySelectorAll("[data-close]").forEach(button => {
        button.addEventListener("click", () => closeOverlay(button.dataset.close));
      });

      document.querySelectorAll(".overlay").forEach(overlay => {
        overlay.addEventListener("click", event => {
          if (event.target === overlay) closeOverlay(overlay.id);
        });
      });

      document.addEventListener("keydown", event => {
        if (event.key === "Escape") {
          const openOverlayElement = [...document.querySelectorAll(".overlay.open")].pop();
          if (openOverlayElement) closeOverlay(openOverlayElement.id);
        }
      });

      document.getElementById("openReport").addEventListener("click", () => openOverlay("reportOverlay"));
      document.getElementById("openChat").addEventListener("click", () => openOverlay("chatOverlay"));

      document.querySelectorAll(".memory-chip").forEach(button => {
        button.addEventListener("click", () => {
          openOverlay("chatOverlay");
          document.getElementById("chatInput").value = `“${button.textContent}”이라고 판단한 근거가 뭐야?`;
        });
      });

      document.querySelectorAll(".filter").forEach(button => {
        button.addEventListener("click", () => {
          document.querySelectorAll(".filter").forEach(item => item.classList.remove("active"));
          button.classList.add("active");
          const filter = button.dataset.filter;
          document.querySelectorAll(".feed-card").forEach(card => {
            card.classList.toggle("is-hidden", filter !== "all" && card.dataset.type !== filter);
          });
        });
      });

      function toast(message) {
        const element = document.getElementById("toast");
        element.textContent = message;
        element.classList.add("show");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => element.classList.remove("show"), 2200);
      }

      document.querySelectorAll(".feed-action-button").forEach(button => {
        button.addEventListener("click", () => {
          button.outerHTML = '<span class="action-done">선택이 반영되었습니다</span>';
          toast("메모리 처리 방식에 반영했습니다.");
        });
      });

      function renderReview() {
        const item = reviewItems[reviewStep];
        document.getElementById("reviewProgress").textContent = `판단 ${reviewStep + 1} / ${reviewItems.length}`;
        document.getElementById("reviewContent").innerHTML = `
          <div class="review-label">${item.label}</div>
          <h2 class="review-title" id="reviewTitle" data-od-id="review-heading">${item.title}</h2>
          <p class="review-subtitle">${item.subtitle}</p>
          <div class="diff-block" data-od-id="memory-diff">
            <div class="diff-side"><small>Before</small><p>${item.before}</p></div>
            <div class="diff-side after"><small>After</small><p>${item.after}</p></div>
          </div>
          <div class="reason-list">
            <strong>이렇게 판단한 근거 ${item.reasons.length}개</strong>
            <ul>${item.reasons.map(reason => `<li>${reason}</li>`).join("")}</ul>
          </div>
          <div class="more-evidence" id="moreEvidence">
            <div class="reason-list">
              <strong>변경 원칙</strong>
              <ul><li>기존 기억은 삭제하지 않고 변경 이력에 보관합니다.</li><li>새 이해는 관련 AI에만 공유됩니다.</li></ul>
            </div>
          </div>
          <div class="drawer-actions">
            <button class="primary-button" id="acceptReview" data-od-id="accept-memory-change">변경 승인</button>
            <button class="secondary-button" id="keepReview" data-od-id="keep-old-memory">기존 이해 유지</button>
            <button class="text-button" id="moreReview" data-od-id="show-more-evidence">더 알아보기</button>
          </div>
        `;

        document.getElementById("acceptReview").addEventListener("click", () => completeReview("변경을 승인했습니다."));
        document.getElementById("keepReview").addEventListener("click", () => completeReview("기존 이해를 유지합니다."));
        document.getElementById("moreReview").addEventListener("click", event => {
          document.getElementById("moreEvidence").classList.toggle("open");
          event.currentTarget.textContent = document.getElementById("moreEvidence").classList.contains("open") ? "접기" : "더 알아보기";
        });
      }

      function completeReview(message) {
        remainingDecisions -= 1;
        document.getElementById("navDecisionCount").textContent = remainingDecisions;
        document.getElementById("decisionNumber").textContent = remainingDecisions;
        toast(message);

        if (reviewStep < reviewItems.length - 1) {
          reviewStep += 1;
          renderReview();
          document.querySelector("#reviewBackdrop .drawer").scrollTop = 0;
        } else {
          closeOverlay("reviewBackdrop");
          document.getElementById("decisionCallout").innerHTML = `
            <div class="decision-copy">
              <div class="decision-number">✓</div>
              <div><strong>이번 주 검토를 마쳤습니다</strong><span>나머지 변화는 자동으로 관리됩니다.</span></div>
            </div>
          `;
          document.getElementById("navDecisionCount").remove();
        }
      }

      function startReview() {
        reviewStep = Math.min(reviewStep, reviewItems.length - 1);
        renderReview();
        openOverlay("reviewBackdrop");
      }

      document.getElementById("startReview").addEventListener("click", startReview);
      document.getElementById("reviewFromReport").addEventListener("click", () => {
        closeOverlay("reportOverlay");
        startReview();
      });

      function updateEvidence(key) {
        const data = evidenceData[key];
        document.getElementById("evidenceTitle").textContent = data.title;
        document.getElementById("evidenceSummary").textContent = data.summary;
        document.getElementById("evidenceList").innerHTML = data.items.map(item =>
          `<div class="evidence-item"><strong>${item[0]}</strong><span>${item[1]}</span></div>`
        ).join("");
      }

      document.querySelectorAll(".model-card").forEach(button => {
        button.addEventListener("click", () => {
          document.querySelectorAll(".model-card").forEach(item => item.classList.remove("active"));
          button.classList.add("active");
          updateEvidence(button.dataset.model);
        });
      });
      updateEvidence("work");

      document.querySelectorAll(".switch").forEach(button => {
        button.addEventListener("click", () => {
          const next = button.getAttribute("aria-pressed") !== "true";
          button.setAttribute("aria-pressed", String(next));
          toast(next ? "AI 연결을 다시 허용했습니다." : "AI의 메모리 접근을 중지했습니다.");
        });
      });

      document.getElementById("pauseSharing").addEventListener("click", event => {
        const switches = [...document.querySelectorAll(".switch")];
        const shouldPause = switches.some(item => item.getAttribute("aria-pressed") === "true");
        switches.forEach(item => item.setAttribute("aria-pressed", shouldPause ? "false" : "true"));
        event.currentTarget.textContent = shouldPause ? "전체 공유 다시 시작" : "전체 공유 일시 중지";
        toast(shouldPause ? "모든 AI의 메모리 접근을 일시 중지했습니다." : "AI별 공유 범위를 다시 적용했습니다.");
      });

      document.getElementById("chatForm").addEventListener("submit", event => {
        event.preventDefault();
        const input = document.getElementById("chatInput");
        const value = input.value.trim();
        if (!value) return;

        const log = document.getElementById("chatLog");
        const userMessage = document.createElement("div");
        userMessage.className = "chat-message user";
        userMessage.textContent = value;
        log.appendChild(userMessage);
        input.value = "";

        const reply = document.createElement("div");
        reply.className = "chat-message ai";
        reply.innerHTML = `현재 저장된 기억과 최근 변화 근거를 비교해볼게요. 이 판단은 고정된 프로필이 아니라, 새로운 행동이 쌓이면 계속 수정되는 이해입니다.<div class="chat-source">관련 기억 분석 중 · 데모 응답</div>`;
        setTimeout(() => {
          log.appendChild(reply);
          log.scrollTop = log.scrollHeight;
        }, 450);
      });
    })();
  </script>
</body>
</html>
</artifact>

