      font-size: 14px;
      line-height: 1.65;
    }

    .evidence-line {
      display: flex;
      gap: 16px;
      color: var(--muted);
      font: 11px var(--mono);
    }

    .feed-action {
      min-width: 104px;
      text-align: right;
    }

    .action-done {
      color: var(--success);
      font-size: 12px;
      font-weight: 680;
    }

    .me-layout {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 350px;
      gap: 22px;
      align-items: start;
    }

    .model-list { border-top: 1px solid var(--border); }

    .model-card {
      width: 100%;
      padding: 25px 4px;
      border: 0;
      border-bottom: 1px solid var(--border);
      background: transparent;
      text-align: left;
      display: grid;
      grid-template-columns: 112px minmax(0, 1fr) 30px;
      gap: 20px;
      align-items: start;
    }

    .model-card:hover .model-statement { color: var(--accent-dark); }

    .model-card.active .model-arrow {
      color: var(--accent-dark);
      transform: translateX(3px);
    }

    .model-category {
      padding-top: 5px;
      color: var(--muted);
      font: 11px var(--mono);
      text-transform: uppercase;
    }

    .model-statement {
      font: 570 20px/1.48 var(--display);
      letter-spacing: -0.035em;
      transition: color 160ms var(--ease);
    }

    .model-arrow {
      padding-top: 5px;
      color: var(--muted);
      font-size: 18px;
      transition: transform 160ms var(--ease);
    }

    .evidence-panel {
      position: sticky;
      top: 28px;
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface);
      box-shadow: var(--shadow);
    }

    .evidence-panel small {
      display: block;
      margin-bottom: 16px;
      color: var(--muted);
      font: 10px var(--mono);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .evidence-panel h3 {
      margin-bottom: 9px;
      font: 650 21px var(--display);
      letter-spacing: -0.04em;
    }

    .evidence-panel > p {
      margin-bottom: 22px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .evidence-list { display: grid; gap: 10px; }

    .evidence-item {
      padding: 13px 0;
      border-top: 1px solid var(--border);
    }

    .evidence-item strong {
      display: block;
      margin-bottom: 5px;
      font-size: 12px;
    }

    .evidence-item span {
      color: var(--muted);
      font-size: 11px;
      line-height: 1.5;
    }

    .control-intro {
      margin-bottom: 24px;
      padding: 19px 22px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--surface);
      display: flex;
      justify-content: space-between;
      gap: 24px;
    }

    .control-intro strong {
      display: block;
      margin-bottom: 5px;
      font-size: 13px;
    }

    .control-intro p {
      margin: 0;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.55;
    }

    .control-table {
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface);
      overflow: hidden;
    }

    .control-row {
      min-height: 104px;
      padding: 19px 22px;
      border-bottom: 1px solid var(--border);
      display: grid;
      grid-template-columns: minmax(230px, 1.2fr) repeat(3, minmax(130px, 0.7fr)) 76px;
      gap: 16px;
      align-items: center;
    }

    .control-row:last-child { border-bottom: 0; }

    .control-head {
      min-height: 54px;
      color: var(--muted);
      font: 10px var(--mono);
      text-transform: uppercase;
      letter-spacing: 0.07em;
    }

    .app-name {
      display: flex;
      align-items: center;
      gap: 13px;
    }

    .app-icon {
      width: 42px;
      height: 42px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--bg);
      display: grid;
      place-items: center;
      font: 650 15px var(--display);
    }

    .app-name strong {
      display: block;
      margin-bottom: 4px;
      font-size: 13px;
    }

    .app-name span {
      color: var(--muted);
      font-size: 11px;
    }

    .permission {
      color: var(--muted);
      font-size: 12px;
    }

    .permission strong {
      display: block;
      margin-bottom: 4px;
      color: var(--fg);
      font-size: 12px;
    }

    .switch {
      width: 50px;
      height: 28px;
      padding: 3px;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: oklch(0.91 0.01 255);
      display: flex;
      align-items: center;
      transition: background 160ms var(--ease), border-color 160ms var(--ease);
    }

    .switch::after {
      content: "";
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: var(--surface);
      box-shadow: 0 1px 4px oklch(0.2 0.03 258 / 0.2);
      transition: transform 180ms var(--ease);
    }

    .switch[aria-pressed="true"] {
      border-color: var(--fg);
      background: var(--fg);
    }

    .switch[aria-pressed="true"]::after { transform: translateX(20px); }

    .overlay {
      position: fixed;
      inset: 0;
      z-index: 10;
      padding: 28px;
      background: oklch(0.11 0.025 258 / 0.52);
      display: grid;
      place-items: center;
      opacity: 0;
      visibility: hidden;
      transition: opacity 140ms var(--ease), visibility 140ms;
    }

    .overlay.align-right { justify-items: end; }

    .overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .dialog,
    .drawer {
      border: 1px solid oklch(1 0 0 / 0.2);
      border-radius: 18px;
      background: var(--surface);
      box-shadow: 0 30px 100px oklch(0.1 0.02 258 / 0.24);
      overflow-y: auto;
      transform: translateY(12px);
      transition: transform 210ms var(--ease);
    }

    .overlay.open .dialog,
    .overlay.open .drawer { transform: translate(0); }

    .dialog {
      width: min(680px, 100%);
      max-height: min(760px, 94vh);
      padding: 30px;
    }

    .drawer {
      width: min(580px, 100%);
      height: 100%;
      padding: 28px;
      transform: translateX(20px);
    }

    .dialog-head,
    .drawer-head {
      margin-bottom: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
    }

    .dialog-head h2 {
      margin: 0;
      font: 650 25px var(--display);
      letter-spacing: -0.045em;
    }

    .drawer-progress {
      color: var(--muted);
      font: 11px var(--mono);
    }

    .close-button {
      flex: 0 0 auto;
      width: 44px;
      height: 44px;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: transparent;
      font-size: 20px;
    }

    .close-button:hover { background: oklch(0.94 0.01 255); }

    .report-lead {
      margin-bottom: 22px;
      color: var(--muted);
      font-size: 14px;
      line-height: 1.7;
    }

    .report-highlight {
      margin-bottom: 18px;
      padding: 22px;
      border-radius: 14px;
      background: var(--night);
      color: white;
    }

    .report-highlight small {
      color: oklch(0.72 0.08 250);
      font: 10px var(--mono);
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .report-highlight h3 {
      max-width: 530px;
      margin: 11px 0 9px;
      font: 620 24px/1.35 var(--display);
      letter-spacing: -0.04em;
    }

    .report-highlight p {
      margin: 0;
      color: oklch(0.76 0.018 255);
      font-size: 12px;
      line-height: 1.6;
    }

    .report-list {
      margin-bottom: 24px;
      border-top: 1px solid var(--border);
    }

    .report-row {
      padding: 15px 0;
      border-bottom: 1px solid var(--border);
      display: grid;
      grid-template-columns: 100px 1fr auto;
      gap: 18px;
      align-items: center;
    }

    .report-row span {
      color: var(--muted);
      font-size: 11px;
    }

    .report-row strong {
      font-size: 13px;
      line-height: 1.5;
    }

    .report-row b {
      font: 650 13px var(--mono);
    }

    .review-label {
      margin-bottom: 14px;
      color: var(--warning);
      font: 650 10px var(--mono);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .review-title {
      margin-bottom: 8px;
      font: 650 31px/1.13 var(--display);
      letter-spacing: -0.055em;
    }

    .review-subtitle {
      margin-bottom: 26px;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.6;
    }

    .diff-block {
      margin-bottom: 22px;
      border: 1px solid var(--border);
      border-radius: 14px;
      overflow: hidden;
    }

    .diff-side {
      padding: 20px;
      background: var(--surface);
    }

    .diff-side + .diff-side { border-top: 1px solid var(--border); }
    .diff-side.after { background: var(--accent-soft); }

    .diff-side small {
      display: block;
      margin-bottom: 8px;
      color: var(--muted);
      font: 10px var(--mono);
      text-transform: uppercase;
    }

    .diff-side p {
      margin: 0;
      font: 570 18px/1.5 var(--display);
      letter-spacing: -0.025em;
    }

    .reason-list {
      margin-bottom: 25px;
      padding: 18px 20px;
      border-left: 2px solid var(--border);
    }

    .reason-list strong {
      display: block;
      margin-bottom: 10px;
      font-size: 12px;
    }

    .reason-list ul {
      margin: 0;
      padding-left: 18px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.8;
    }

    .more-evidence {
      max-height: 0;
      overflow: hidden;
      opacity: 0;
      transition: max-height 200ms var(--ease), opacity 160ms var(--ease);
    }

    .more-evidence.open {
      max-height: 180px;
      opacity: 1;
    }

    .drawer-actions {
      display: flex;
      align-items: center;
      gap: 9px;
      flex-wrap: wrap;
    }

    .chat-drawer {
      padding: 0;
      overflow: hidden;
      display: grid;
      grid-template-rows: auto 1fr auto;
    }

    .chat-head {
      min-height: 82px;
      padding: 18px 22px;
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .chat-head strong {
      display: block;
      margin-bottom: 4px;
      font-size: 14px;
    }

    .chat-head span {
      color: var(--muted);
      font-size: 11px;
    }

    .chat-log {
      min-height: 0;
      padding: 26px 22px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    .chat-message {
      max-width: 84%;
      padding: 13px 15px;
      border-radius: 14px;
      font-size: 13px;
      line-height: 1.58;
    }

    .chat-message.ai {
      align-self: flex-start;
      border: 1px solid var(--border);
      border-bottom-left-radius: 4px;
      background: var(--surface);
    }

    .chat-message.user {
      align-self: flex-end;
      border-bottom-right-radius: 4px;
      background: var(--fg);
      color: white;
    }

    .chat-source {
      margin-top: 8px;
      color: var(--muted);
      font: 10px var(--mono);
    }

    .chat-composer {
      padding: 14px;
      border-top: 1px solid var(--border);
      background: var(--surface);
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
    }

    .chat-input {
      min-height: 46px;
      min-width: 0;
      padding: 0 14px;
      border: 1px solid var(--border);
      border-radius: 10px;
      background: var(--bg);
      color: var(--fg);
    }

    .chat-input::placeholder { color: var(--muted); }

    .toast {
      position: fixed;
      left: 50%;
      bottom: 28px;
      z-index: 20;
      min-width: 260px;
      padding: 13px 17px;
      border-radius: 10px;
      background: var(--fg);
      color: var(--surface);
      text-align: center;
      font-size: 12px;
      box-shadow: var(--shadow);
      opacity: 0;
      transform: translate(-50%, 12px);
      pointer-events: none;
      transition: opacity 170ms var(--ease), transform 170ms var(--ease);
    }

    .toast.show {
      opacity: 1;
      transform: translate(-50%, 0);
    }

    @media (max-width: 1160px) {
      .memory-hero { min-height: 700px; }
      .hero-copy { width: 58%; padding-left: 42px; }
      .orbit-stage { right: -95px; width: 57%; }
      .summary-grid { grid-template-columns: repeat(2, 1fr); }
      .summary-item:nth-child(2) { border-right: 0; }
      .summary-item:nth-child(-n+2) { border-bottom: 1px solid var(--border); }
      .me-layout { grid-template-columns: 1fr; }
      .evidence-panel { position: static; }
      .control-row { grid-template-columns: minmax(220px, 1fr) repeat(3, 110px) 60px; }
    }

    @media (max-width: 900px) {
      .app-shell { display: block; }
      .sidebar {
        position: static;
        width: 100%;
        height: auto;
        padding: 14px 18px;
        border-right: 0;
        border-bottom: 1px solid var(--border);
        flex-direction: row;
        align-items: center;
        gap: 20px;
      }
      .nav { margin-left: auto; grid-auto-flow: column; }
      .nav-button { min-height: 44px; }
      .nav-button span:first-child { display: none; }
      .sidebar-note { display: none; }
      .main { padding: 16px 20px 48px; }
      .memory-hero { min-height: 900px; }
      .hero-copy {
        width: 100%;
        min-height: 390px;
        padding: 52px 32px 30px;
      }
      .hero-copy h1 { font-size: 50px; }
      .orbit-stage {
        top: 350px;
        right: 0;
        width: 100%;
        height: 450px;
        transform: scale(0.86);
      }
      .hero-report-strip {
        grid-template-columns: repeat(3, 1fr);
        bottom: 15px;
      }
      .report-intro { display: none; }
      .feed-card { grid-template-columns: 1fr; gap: 10px; }
      .feed-action { text-align: left; }
      .control-table { overflow-x: auto; }
      .control-row { min-width: 820px; }
    }

    @media (max-width: 620px) {
      .main { padding-inline: 12px; }
      .memory-hero { min-height: 820px; border-radius: 18px; }
      .hero-copy { padding-inline: 24px; }
      .hero-copy h1 { font-size: 42px; }
      .orbit-stage {
        top: 350px;
        transform: scale(0.7);
      }
      .hero-report-strip { padding: 0 12px; }
      .report-stat { padding-left: 12px; }
      .summary-grid { grid-template-columns: 1fr; }
      .summary-item {
        min-height: 96px;
        border-right: 0;
        border-bottom: 1px solid var(--border);
      }
      .decision-callout {
        align-items: flex-start;
        flex-direction: column;
      }
      .model-card { grid-template-columns: 86px 1fr 20px; gap: 10px; }
      .overlay { padding: 10px; }
      .report-row { grid-template-columns: 78px 1fr; }
      .report-row b { grid-column: 2; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <div class="app-shell">
    <aside class="sidebar" data-od-id="primary-navigation">
      <div class="brand" data-od-id="product-brand">
        <div class="brand-mark" aria-hidden="true">ML</div>
        <div class="brand-name">Memory Lens</div>
      </div>

      <nav class="nav" aria-label="주요 화면">
        <button class="nav-button active" data-screen="home" data-od-id="nav-home">
          <span>Home</span>
          <span class="nav-count" id="navDecisionCount">2</span>
        </button>
        <button class="nav-button" data-screen="me" data-od-id="nav-me"><span>Me</span></button>
        <button class="nav-button" data-screen="control" data-od-id="nav-control"><span>Control</span></button>
      </nav>

      <div class="sidebar-note" data-od-id="automation-status">
        <strong>자동 관리 중</strong>
        <p>확신할 수 있는 기억은 조용히 정리하고, 판단이 필요한 변화만 보여드립니다.</p>
      </div>
    </aside>

    <main class="main" id="content">
      <header class="topbar" data-od-id="top-status">
        <div class="status-pill"><span class="status-dot" aria-hidden="true"></span>마지막 동기화 · 방금 전</div>
        <div class="avatar" aria-label="사용자 프로필">IH</div>
      </header>

      <section class="screen active" id="home" data-od-id="home-screen">
        <div class="memory-hero" data-od-id="memory-orbit-hero">
          <div class="hero-copy">
            <div class="hero-eyebrow">Weekly memory intelligence</div>
            <h1 data-od-id="home-heading">이번 주, 당신에 대한 이해가 달라졌습니다.</h1>
            <p>37개의 변화를 분석했고 대부분은 조용히 정리했습니다. 지금은 AI가 발견한 흐름을 리포트로 보거나, 당신의 기억과 직접 대화할 수 있습니다.</p>
            <div class="hero-actions">
              <button class="hero-primary" id="openReport" data-od-id="open-memory-report">리포트 열기</button>
              <button class="hero-secondary" id="openChat" data-od-id="open-memory-chat">메모리와 대화</button>
            </div>
          </div>

          <div class="orbit-stage" aria-label="사용자의 기억이 중심 모델 주위를 움직이는 시각화">
            <div class="orbit-ring one"></div>
            <div class="orbit-ring two"></div>
            <div class="orbit-ring three"></div>

            <div class="memory-core" data-od-id="memory-core">
              <div class="core-label">
                <strong>94%</strong>
                <span>자동 정리됨</span>
              </div>
            </div>

            <div class="orbit-track">
              <div class="orbit-memory"><button class="memory-chip">디자인 완성도를 중시함</button></div>
              <div class="orbit-memory"><button class="memory-chip">AI 코딩 도구를 적극 사용</button></div>
              <div class="orbit-memory"><button class="memory-chip">해커톤에서는 속도 우선</button></div>
              <div class="orbit-memory"><button class="memory-chip">Flutter 사용 빈도 감소</button></div>
              <div class="orbit-memory"><button class="memory-chip">정보량이 절제된 UI 선호</button></div>
              <div class="orbit-memory"><button class="memory-chip">여러 프로젝트를 동시 탐색</button></div>
            </div>
          </div>

          <div class="hero-report-strip" data-od-id="hero-report-summary">
            <div class="report-intro">
              <strong>2026년 8월 2주 차</strong>
              <span>개인 메모리 인텔리전스 리포트</span>
            </div>
            <div class="report-stat"><strong>37</strong><span>발견한 변화</span></div>
            <div class="report-stat"><strong>2</strong><span>판단 필요</span></div>
            <div class="report-stat"><strong>18</strong><span>자동 보관</span></div>
          </div>
        </div>

        <div class="summary-grid" data-od-id="weekly-summary">
          <article class="summary-item" data-od-id="summary-strengthened"><span class="summary-label">강화된 이해</span><span class="summary-value">12</span></article>
          <article class="summary-item" data-od-id="summary-outdated"><span class="summary-label">오래된 것으로 추정</span><span class="summary-value">4</span></article>
          <article class="summary-item" data-od-id="summary-contextualized"><span class="summary-label">맥락을 찾은 충돌</span><span class="summary-value">3</span></article>
          <article class="summary-item" data-od-id="summary-archived"><span class="summary-label">자동 보관</span><span class="summary-value">18</span></article>
        </div>

        <div class="decision-callout" id="decisionCallout" data-od-id="decision-callout">
          <div class="decision-copy">
            <div class="decision-number" id="decisionNumber">2</div>
            <div><strong>당신의 판단이 필요한 변화가 있습니다</strong><span>예상 소요 시간 47초</span></div>
          </div>
          <button class="primary-button" id="startReview" data-od-id="start-review">검토 시작</button>
        </div>

        <div class="section-head">
          <div>
            <h2 data-od-id="feed-heading">무엇이 달라졌나요</h2>
            <p>아무것도 하지 않으면 신뢰도에 따라 자동으로 반영됩니다.</p>
          </div>
          <div class="filter-row" role="group" aria-label="변화 유형 필터">
            <button class="filter active" data-filter="all" data-od-id="filter-all">전체</button>
            <button class="filter" data-filter="changed" data-od-id="filter-changed">변화</button>
            <button class="filter" data-filter="fading" data-od-id="filter-fading">소멸</button>
            <button class="filter" data-filter="context" data-od-id="filter-context">맥락</button>
          </div>
        </div>

        <div class="feed" data-od-id="memory-change-feed">
          <article class="feed-card" data-type="changed" data-od-id="feed-card-framework">
