        },
        {
          label: "맥락이 필요한 충돌",
          title: "두 선호를 조건부 기억으로 바꿀까요?",
          subtitle: "둘 중 하나를 지우는 대신, 각각이 적용되는 상황을 발견했습니다.",
          before: "빠르게 MVP를 만드는 것을 선호함 ↔ 디자인 완성도를 매우 중요하게 생각함",
          after: "해커톤에서는 속도를 우선하고, 소비자 제품에서는 디자인 완성도를 우선함",
          reasons: ["해커톤 대화에서 실행 속도 11회 강조", "소비자 제품 리뷰에서 시각 완성도 9회 강조", "상황별 선택이 최근 4개월간 일관됨"]
        }
      ];

      const evidenceData = {
        work: {
          title: "속도와 완성도의 조건",
          summary: "서로 모순되어 보이던 두 선호가 작업 맥락에 따라 달라진다는 패턴을 발견했습니다.",
          items: [["해커톤", "짧은 시간 안에 작동하는 결과를 우선한 대화 11건"], ["소비자 제품", "시각적 마감과 경험 품질을 강조한 대화 9건"], ["최근 확인", "3일 전 · 제품 디자인 논의"]]
        },
        coding: {
          title: "프레임워크보다 문제 적합성",
          summary: "Flutter 경험은 여전히 강하지만 최근 선택은 제품 요구와 배포 환경에 따라 달라지고 있습니다.",
          items: [["Flutter", "최근 90일 새 프로젝트 1건"], ["Swift·웹", "동일 기간 탐색 및 구현 13건"], ["최근 확인", "어제 · 데스크탑 프로토타입 논의"]]
        },
        projects: {
          title: "넓게 탐색하고 빠르게 전환",
          summary: "초기에는 여러 가능성을 비교하고, 신호가 약한 방향은 유지 비용을 키우기 전에 전환합니다.",
          items: [["동시 탐색", "최근 프로젝트 아이디어 7개"], ["방향 전환", "초기 검증 후 범위를 줄인 사례 4개"], ["최근 확인", "5일 전 · MVP 범위 결정"]]
        },
        preferences: {
          title: "절제된 정보와 강한 위계",
          summary: "단순히 여백이 많은 화면보다, 중요도에 따라 정보가 명확히 압축된 인터페이스를 선호합니다.",
          items: [["반복 표현", "정보 밀도에 대한 피드백 19건"], ["선호 패턴", "하나의 명확한 주 행동과 강한 제목 위계"], ["최근 확인", "오늘 · Memory Lens 설계"]]
        },
        current: {
          title: "현재의 관심사",
          summary: "시간에 민감한 상태로 취급하며, 활동 신호가 줄어들면 자동으로 약화합니다.",
          items: [["해커톤", "최근 30일 관련 활동 12건"], ["AI 제품", "아이디어·프로토타입 대화 18건"], ["자동 만료", "활동이 45일 없으면 재검토"]]
        }
      };

      function showScreen(id) {
        screens.forEach(screen => screen.classList.toggle("active", screen.id === id));
        navButtons.forEach(button => button.classList.toggle("active", button.dataset.screen === id));
        localStorage.setItem("memory-lens-screen", id);
      }

      navButtons.forEach(button => button.addEventListener("click", () => showScreen(button.dataset.screen)));
      showScreen(storedScreen);

      function openOverlay(id) {
        const overlay = document.getElementById(id);
        overlay.classList.add("open");
        overlay.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
        setTimeout(() => overlay.querySelector("button, input")?.focus(), 20);
      }

      function closeOverlay(id) {
        const overlay = document.getElementById(id);
        overlay.classList.remove("open");
        overlay.setAttribute("aria-hidden", "true");
        if (!document.querySelector(".overlay.open")) document.body.style.overflow = "";
      }

      document.querySelectorAll("[data-close]").forEach(button => {
        button.addEventListener("click", () => closeOverlay(button.dataset.close));
      });

      document.querySelectorAll(".overlay").forEach(overlay => {
        overlay.addEventListener("click", event => {
          if (event.target === overlay) closeOverlay(overlay.id);
        });
      });

      document.addEventListener("keydown", event => {
        if (event.key === "Escape") {
          const openOverlayElement = [...document.querySelectorAll(".overlay.open")].pop();
          if (openOverlayElement) closeOverlay(openOverlayElement.id);
        }
      });

      document.getElementById("openReport").addEventListener("click", () => openOverlay("reportOverlay"));
      document.getElementById("openChat").addEventListener("click", () => openOverlay("chatOverlay"));

      document.querySelectorAll(".memory-chip").forEach(button => {
        button.addEventListener("click", () => {
          openOverlay("chatOverlay");
          document.getElementById("chatInput").value = `“${button.textContent}”이라고 판단한 근거가 뭐야?`;
        });
