스케치보드용 새 파일을 추가합니다. 기존 앱을 참조하므로 두 HTML은 같은 폴더에 두면 됩니다.

<artifact identifier="memory-lens-sketchboard" type="text/html" title="Memory Lens 스케치보드">
<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Memory Lens — 디자인 스케치보드</title>
  <style>
    :root {
      --bg: oklch(0.91 0.009 255);
      --surface: oklch(0.985 0.004 255);
      --fg: oklch(0.19 0.022 258);
      --muted: oklch(0.5 0.02 258);
      --border: oklch(0.79 0.014 255);
      --accent: oklch(0.55 0.19 255);
      --board: oklch(0.865 0.012 255);
      --body: "Pretendard Variable", "Pretendard", "Apple SD Gothic Neo", "Segoe UI Variable", sans-serif;
      --mono: "SFMono-Regular", "Cascadia Code", Consolas, monospace;
      --ease: cubic-bezier(0.23, 1, 0.32, 1);
    }

    * { box-sizing: border-box; }

    html, body {
      width: 100%;
      min-height: 100%;
      margin: 0;
      overflow: hidden;
      background: var(--board);
      color: var(--fg);
      font-family: var(--body);
    }

    button, select, input { font: inherit; }

    button {
      color: inherit;
      cursor: pointer;
    }

    button:focus-visible,
    select:focus-visible,
    input:focus-visible {
      outline: 3px solid oklch(0.7 0.15 255);
      outline-offset: 2px;
    }

    .board-shell {
      height: 100vh;
      display: grid;
      grid-template-rows: 64px minmax(0, 1fr);
    }

    .toolbar {
      position: relative;
      z-index: 10;
      min-width: 0;
      padding: 0 18px;
      border-bottom: 1px solid var(--border);
      background: oklch(0.975 0.006 255 / 0.94);
      backdrop-filter: blur(18px);
      display: flex;
      align-items: center;
      gap: 18px;
      box-shadow: 0 4px 18px oklch(0.2 0.02 258 / 0.07);
    }

    .brand {
      flex: 0 0 auto;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .brand-mark {
      width: 30px;
      height: 30px;
      border: 1px solid var(--fg);
      border-radius: 50%;
      display: grid;
      place-items: center;
      font-size: 10px;
      font-weight: 750;
      letter-spacing: -0.04em;
    }

    .brand-copy strong {
      display: block;
      margin-bottom: 1px;
      font-size: 13px;
      letter-spacing: -0.025em;
    }

    .brand-copy span {
      display: block;
      color: var(--muted);
      font: 9px var(--mono);
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .toolbar-divider {
      width: 1px;
      height: 28px;
      background: var(--border);
    }

    .toolbar-section {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .toolbar-section.push { margin-left: auto; }

    .tool-button {
      min-height: 38px;
      padding: 0 12px;
      border: 1px solid transparent;
      border-radius: 8px;
      background: transparent;
      font-size: 12px;
      transition: background 150ms var(--ease), border-color 150ms var(--ease);
    }

    .tool-button:hover {
      border-color: var(--border);
      background: var(--surface);
    }

    .tool-button.primary {
      border-color: var(--fg);
      background: var(--fg);
      color: white;
      font-weight: 680;
    }

    .tool-button.primary:hover {
      background: oklch(0.28 0.025 258);
    }

    .zoom-group {
      min-height: 38px;
      padding: 3px;
      border: 1px solid var(--border);
      border-radius: 9px;
      background: var(--surface);
      display: flex;
      align-items: center;
    }

    .zoom-button {
      min-width: 42px;
      min-height: 30px;
      padding: 0 8px;
      border: 0;
      border-radius: 6px;
      background: transparent;
      color: var(--muted);
      font-size: 11px;
    }

    .zoom-button:hover {
      background: var(--bg);
      color: var(--fg);
    }

    .zoom-button.active {
      background: var(--fg);
      color: white;
    }

    .board-viewport {
      position: relative;
      min-width: 0;
      min-height: 0;
      overflow: auto;
      cursor: grab;
    }

    .board-viewport.is-panning { cursor: grabbing; }

    .board-canvas {
      position: relative;
      min-width: 100%;
      min-height: 100%;
      padding: 66px;
      background-color: var(--board);
      background-image:
        linear-gradient(oklch(0.63 0.01 255 / 0.2) 1px, transparent 1px),
        linear-gradient(90deg, oklch(0.63 0.01 255 / 0.2) 1px, transparent 1px),
        radial-gradient(circle, oklch(0.62 0.01 255 / 0.48) 1px, transparent 1px);
      background-size: 80px 80px, 80px 80px, 16px 16px;
    }

    .board-header {
      max-width: 720px;
      margin-bottom: 42px;
    }

    .board-eyebrow {
      margin-bottom: 10px;
      color: var(--muted);
      font: 10px var(--mono);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .board-header h1 {
      margin: 0 0 9px;
      font-size: 28px;
      line-height: 1.15;
      letter-spacing: -0.045em;
    }

    .board-header p {
      max-width: 620px;
      margin: 0;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.65;
    }

    .artboard-grid {
      display: flex;
      align-items: flex-start;
      gap: 34px;
      width: max-content;
      min-width: 100%;
      padding-bottom: 90px;
      flex-wrap: wrap;
    }

    .artboard-card {
      flex: 0 0 auto;
      min-width: 0;
    }

    .artboard-meta {
      min-height: 46px;
      margin-bottom: 10px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .artboard-title-wrap {
      min-width: 0;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .artboard-index {
      width: 25px;
      height: 25px;
      flex: 0 0 auto;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: var(--surface);
      display: grid;
      place-items: center;
      color: var(--muted);
      font: 9px var(--mono);
    }

    .title-input {
      width: 156px;
      min-height: 34px;
      padding: 0 8px;
      border: 1px solid transparent;
      border-radius: 6px;
      background: transparent;
      color: var(--fg);
      font-weight: 680;
      letter-spacing: -0.025em;
    }

    .title-input:hover,
    .title-input:focus {
      border-color: var(--border);
      background: var(--surface);
    }

    .screen-select {
      min-height: 34px;
      padding: 0 28px 0 9px;
      border: 1px solid var(--border);
      border-radius: 7px;
      background: var(--surface);
      color: var(--fg);
      font-size: 11px;
    }

    .artboard-actions {
      display: flex;
      gap: 4px;
    }

    .icon-button {
      min-width: 34px;
      min-height: 34px;
      padding: 0 8px;
      border: 1px solid transparent;
      border-radius: 7px;
      background: transparent;
      color: var(--muted);
      font: 11px var(--mono);
    }

    .icon-button:hover {
      border-color: var(--border);
      background: var(--surface);
      color: var(--fg);
    }

    .artboard-frame {
      position: relative;
      border: 1px solid oklch(0.6 0.01 255);
      border-radius: 6px;
      background: white;
      box-shadow:
        0 1px 2px oklch(0.2 0.02 258 / 0.16),
        0 18px 50px oklch(0.2 0.025 258 / 0.13);
      overflow: hidden;
      transition: box-shadow 180ms var(--ease), transform 180ms var(--ease);
    }

    .artboard-card:hover .artboard-frame {
      box-shadow:
        0 1px 2px oklch(0.2 0.02 258 / 0.18),
        0 24px 70px oklch(0.2 0.025 258 / 0.18);
      transform: translateY(-2px);
    }

    .artboard-frame iframe {
      position: absolute;
      top: 0;
      left: 0;
      width: 1440px;
      height: 900px;
      border: 0;
      background: white;
      transform-origin: top left;
      pointer-events: none;
    }

    .artboard-frame.inspecting iframe { pointer-events: auto; }

    .artboard-shield {
      position: absolute;
      inset: 0;
      z-index: 2;
      border: 0;
      background: transparent;
      cursor: zoom-in;
    }

    .artboard-frame.inspecting .artboard-shield {
      display: none;
    }

    .inspect-badge {
      position: absolute;
      right: 9px;
      bottom: 9px;
      z-index: 3;
      min-height: 28px;
      padding: 0 9px;
      border: 1px solid oklch(1 0 0 / 0.2);
      border-radius: 7px;
      background: oklch(0.18 0.025 258 / 0.88);
      color: white;
      display: none;
      align-items: center;
      font-size: 9px;
      backdrop-filter: blur(10px);
    }

    .artboard-frame.inspecting .inspect-badge { display: flex; }

    .empty-board {
      width: 440px;
      min-height: 280px;
      padding: 38px;
      border: 1px dashed oklch(0.62 0.02 255);
      border-radius: 10px;
      background: oklch(0.94 0.008 255 / 0.5);
      display: grid;
      place-items: center;
      text-align: center;
    }

    .empty-board strong {
      display: block;
      margin-bottom: 8px;
      font-size: 14px;
    }

    .empty-board p {
      max-width: 300px;
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.6;
    }

    .status-toast {
      position: fixed;
      left: 50%;
      bottom: 24px;
      z-index: 20;
      min-width: 240px;
      padding: 12px 16px;
      border-radius: 9px;
      background: var(--fg);
      color: white;
      text-align: center;
      font-size: 11px;
      box-shadow: 0 16px 44px oklch(0.2 0.03 258 / 0.2);
      opacity: 0;
      transform: translate(-50%, 10px);
      pointer-events: none;
      transition: opacity 160ms var(--ease), transform 160ms var(--ease);
    }

    .status-toast.show {
      opacity: 1;
      transform: translate(-50%, 0);
    }

    @media (max-width: 900px) {
      .brand-copy span,
      .toolbar-divider,
      .toolbar-label { display: none; }
      .toolbar { gap: 8px; padding-inline: 10px; }
      .toolbar-section.push { margin-left: auto; }
      .board-canvas { padding: 38px 24px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <div class="board-shell">
    <header class="toolbar" data-od-id="sketchboard-toolbar">
      <div class="brand">
        <div class="brand-mark">ML</div>
        <div class="brand-copy">
          <strong>Memory Lens</strong>
          <span>Sketch board</span>
        </div>
      </div>

      <div class="toolbar-divider"></div>

      <div class="toolbar-section">
        <span class="toolbar-label" style="color:var(--muted);font-size:11px;">배율</span>
        <div class="zoom-group" role="group" aria-label="아트보드 배율">
          <button class="zoom-button" data-zoom="0.26">26%</button>
          <button class="zoom-button active" data-zoom="0.32">32%</button>
          <button class="zoom-button" data-zoom="0.42">42%</button>
          <button class="zoom-button" data-zoom="0.56">56%</button>
        </div>
      </div>

      <div class="toolbar-section push">
        <button class="tool-button" id="resetBoard" data-od-id="reset-board">기본 보드</button>
        <button class="tool-button primary" id="addArtboard" data-od-id="add-artboard">시안 추가</button>
      </div>
    </header>

    <div class="board-viewport" id="boardViewport">
      <main class="board-canvas" data-od-id="sketchboard-canvas">
        <header class="board-header">
          <div class="board-eyebrow">Memory Lens · Desktop exploration</div>
          <h1 data-od-id="board-heading">핵심 화면 스케치보드</h1>
          <p>모든 화면을 같은 배율로 비교하세요. 아트보드를 복제해 다른 시안을 만들고, 화면 유형을 바꾸거나 개별 화면을 크게 열 수 있습니다.</p>
        </header>

        <section class="artboard-grid" id="artboardGrid" data-od-id="artboard-grid"></section>
      </main>
    </div>
  </div>

  <div class="status-toast" id="toast" role="status" aria-live="polite"></div>

  <script>
    (() => {
      const SOURCE_FILE = "memory-lens-desktop.html";
      const FRAME_WIDTH = 1440;
      const FRAME_HEIGHT = 900;
      const DEFAULT_BOARDS = [
        { id: crypto.randomUUID(), title: "Home · Memory Orbit", screen: "home" },
        { id: crypto.randomUUID(), title: "Me · AI가 이해한 나", screen: "me" },
        { id: crypto.randomUUID(), title: "Control · 공유 범위", screen: "control" }
      ];

      const screenLabels = {
        home: "Home",
        me: "Me",
        control: "Control"
      };

      let zoom = Number(localStorage.getItem("memory-lens-board-zoom")) || 0.32;
      let boards = loadBoards();
      let toastTimer;

      const grid = document.getElementById("artboardGrid");
      const viewport = document.getElementById("boardViewport");

      function loadBoards() {
        try {
          const stored = JSON.parse(localStorage.getItem("memory-lens-artboards"));
          if (Array.isArray(stored) && stored.length) return stored;
        } catch (_) {}
        return DEFAULT_BOARDS;
      }

      function saveBoards() {
        localStorage.setItem("memory-lens-artboards", JSON.stringify(boards));
      }

      function toast(message) {
        const element = document.getElementById("toast");
        element.textContent = message;
        element.classList.add("show");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => element.classList.remove("show"), 1800);
      }

      function activateFrameScreen(iframe, screen) {
        try {
          const doc = iframe.contentDocument;
          if (!doc) return;
          const button = doc.querySelector(`.nav-button[data-screen="${screen}"]`);
          if (button) button.click();
        } catch (_) {
          toast("화면 미리보기는 동일한 프로젝트 서버에서 열어주세요.");
        }
      }

      function renderBoards() {
        grid.innerHTML = "";

        if (!boards.length) {
          grid.innerHTML = `
            <div class="empty-board">
              <div>
                <strong>아트보드가 없습니다</strong>
                <p>시안을 추가해 Home, Me, Control 화면을 한 보드 위에서 비교해보세요.</p>
                <button class="tool-button primary" id="emptyAdd">첫 시안 추가</button>
              </div>
            </div>
          `;
          document.getElementById("emptyAdd").addEventListener("click", addBoard);
          return;
        }

        boards.forEach((board, index) => {
          const card = document.createElement("article");
          card.className = "artboard-card";
          card.dataset.boardId = board.id;
          card.setAttribute("data-od-id", `artboard-${index + 1}`);
          card.innerHTML = `
            <div class="artboard-meta">
              <div class="artboard-title-wrap">
                <span class="artboard-index">${String(index + 1).padStart(2, "0")}</span>
