        <button class="tool-button" id="fitBoard" data-od-id="fit-board">전체 맞춤</button>
        <button class="tool-button" id="resetBoard" data-od-id="reset-board">기본 보드</button>
        <button class="tool-button primary" id="addArtboard" data-od-id="add-artboard">시안 추가</button>
      </div>
    </header>

    <div class="board-viewport" id="boardViewport">
      <main class="board-canvas" data-od-id="sketchboard-canvas">
        <header class="board-header">
          <div class="board-eyebrow">Memory Lens · Desktop product study</div>
          <h1 data-od-id="board-heading">기억을 관리하는 화면이 아니라, AI의 이해를 검토하는 경험</h1>
          <p>코어 플로우와 Home의 시각 방향을 한 캔버스에서 비교합니다. 화면을 복제해 탐색하고, 포커스 모드에서 실제 인터랙션을 확인하세요.</p>
        </header>

        <section class="board-section" data-od-id="core-flow-section">
          <div class="section-heading">
            <div class="section-heading-main">
              <span class="section-number">01</span>
              <div>
                <h2 data-od-id="core-flow-heading">코어 플로우</h2>
                <p>변화 확인 → 자기 모델 탐색 → AI별 공유 범위 제어</p>
              </div>
            </div>
            <span class="section-note">제품 구조와 작업 밀도를 비교하는 화면군</span>
          </div>
          <div class="artboard-grid" id="flowGrid" data-od-id="core-flow-grid"></div>
        </section>

        <section class="board-section" data-od-id="direction-study-section">
          <div class="section-heading">
            <div class="section-heading-main">
              <span class="section-number">02</span>
              <div>
                <h2 data-od-id="direction-study-heading">Home 방향 시안</h2>
                <p>동일한 기억 리포트 경험을 서로 다른 정보 태도로 비교</p>
              </div>
            </div>
            <span class="section-note">장식이 아니라 이해 속도와 신뢰감의 차이를 평가</span>
          </div>
          <div class="artboard-grid" id="studyGrid" data-od-id="direction-study-grid"></div>
        </section>
      </main>
    </div>
  </div>

  <div class="focus-layer" id="focusLayer" aria-hidden="true">
    <section class="focus-panel" role="dialog" aria-modal="true" aria-labelledby="focusTitle">
      <header class="focus-toolbar">
        <strong id="focusTitle">시안 포커스</strong>
        <button class="focus-close" id="closeFocus" aria-label="포커스 모드 닫기">닫기</button>
      </header>
      <div class="focus-viewport" id="focusViewport"></div>
    </section>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite"></div>

  <script>
    (() => {
      const SOURCE_FILE = "memory-lens-desktop.html";
      const FRAME_WIDTH = 1440;
      const FRAME_HEIGHT = 900;

      const VARIANTS = {
        orbit: {
          label: "Orbit Core",
          note: "기억 조각의 움직임과 중심 코어를 전면에 둔 현재 방향. 가장 강한 제품 정체성을 제공합니다."
        },
        quiet: {
          label: "Quiet Intelligence",
          note: "밝은 배경과 낮은 대비의 오빗으로 신뢰와 설명 가능성을 우선합니다."
        },
        signal: {
          label: "Signal Grid",
          note: "리포트 수치와 변화 신호를 더 빠르게 스캔하도록 밀도를 높인 운영형 방향입니다."
        }
      };

      const DEFAULT_BOARDS = [
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Home · What changed",
          screen: "home",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Me · What AI thinks",
          screen: "me",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Control · Who can know",
          screen: "control",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "A · Orbit Core",
          screen: "home",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "B · Quiet Intelligence",
          screen: "home",
          variant: "quiet"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "C · Signal Grid",
          screen: "home",
          variant: "signal"
        }
      ];

      const screenLabels = {
        home: "Home",
        me: "Me",
        control: "Control"
      };

      let zoom = Number(localStorage.getItem("memory-lens-board-zoom")) || 0.3;
      let boards = loadBoards();
      let toastTimer;

      const viewport = document.getElementById("boardViewport");
      const flowGrid = document.getElementById("flowGrid");
      const studyGrid = document.getElementById("studyGrid");

      function loadBoards() {
        try {
          const stored = JSON.parse(localStorage.getItem("memory-lens-creative-board"));
          if (Array.isArray(stored) && stored.length) return stored;
        } catch (_) {}
        return DEFAULT_BOARDS;
      }

      function saveBoards() {
        localStorage.setItem("memory-lens-creative-board", JSON.stringify(boards));
      }

      function escapeHTML(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function toast(message) {
        const element = document.getElementById("toast");
        element.textContent = message;
        element.classList.add("show");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => element.classList.remove("show"), 1800);
      }

      function sizeFrame(frame, iframe) {
        frame.style.width = `${FRAME_WIDTH * zoom}px`;
        frame.style.height = `${FRAME_HEIGHT * zoom}px`;
        iframe.style.transform = `scale(${zoom})`;
      }

      function variantCSS(variant) {
        if (variant === "quiet") {
          return `
            .memory-hero {
              background: oklch(0.955 0.012 255) !important;
              color: oklch(0.19 0.022 258) !important;
              box-shadow: 0 18px 50px oklch(0.2 0.02 258 / 0.1) !important;
            }
            .memory-hero::before { opacity: .07 !important; }
            .hero-copy > p { color: oklch(0.48 0.025 258) !important; }
            .hero-eyebrow { color: oklch(0.46 0.12 255) !important; }
            .hero-primary {
              border-color: oklch(0.19 0.022 258) !important;
              background: oklch(0.19 0.022 258) !important;
              color: white !important;
            }
            .hero-secondary {
              border-color: oklch(0.72 0.02 255) !important;
              background: oklch(1 0 0 / .6) !important;
              color: oklch(0.19 0.022 258) !important;
            }
            .orbit-ring { border-color: oklch(0.52 0.08 255 / .18) !important; }
            .orbit-stage { filter: saturate(.72); }
            .memory-chip {
              border-color: oklch(0.76 0.025 255) !important;
              background: oklch(0.99 0.004 255 / .82) !important;
              color: oklch(0.25 0.025 258) !important;
              box-shadow: 0 8px 24px oklch(0.2 0.02 258 / .09) !important;
            }
            .hero-report-strip {
              border-color: oklch(0.77 0.018 255) !important;
              background: oklch(0.99 0.004 255 / .82) !important;
              color: oklch(0.19 0.022 258) !important;
            }
            .report-intro span, .report-stat span {
              color: oklch(0.5 0.02 258) !important;
            }
            .report-stat { border-color: oklch(0.82 0.015 255) !important; }
          `;
        }

        if (variant === "signal") {
          return `
            .memory-hero { min-height: 560px !important; }
            .hero-copy {
              width: 61% !important;
              min-height: 460px !important;
              padding-top: 42px !important;
            }
            .hero-copy h1 {
              max-width: 760px !important;
              font-size: 62px !important;
            }
            .orbit-stage {
              right: -130px !important;
              width: 48% !important;
              opacity: .68 !important;
              transform: scale(.83) !important;
            }
            .hero-report-strip {
              left: 0 !important;
              right: 0 !important;
              bottom: 0 !important;
              min-height: 82px !important;
              border-left: 0 !important;
              border-right: 0 !important;
              border-bottom: 0 !important;
              border-radius: 0 !important;
            }
            .summary-grid {
              grid-template-columns: repeat(4, 1fr) !important;
              margin-top: -8px !important;
            }
            .summary-item { min-height: 108px !important; }
          `;
        }

        return "";
      }

      function prepareFrame(iframe, board) {
        try {
          const doc = iframe.contentDocument;
          if (!doc) return;

          const screenButton = doc.querySelector(`.nav-button[data-screen="${board.screen}"]`);
          if (screenButton) screenButton.click();

          const oldStyle = doc.getElementById("board-variant-style");
          if (oldStyle) oldStyle.remove();

          const style = doc.createElement("style");
          style.id = "board-variant-style";
          style.textContent = variantCSS(board.variant);
          doc.head.appendChild(style);
          doc.body.dataset.boardVariant = board.variant;
        } catch (_) {
          toast("미리보기는 프로젝트 서버에서 열어주세요.");
        }
      }

      function createCard(board, index) {
        const card = document.createElement("article");
        card.className = "artboard-card";
        card.dataset.boardId = board.id;
        card.setAttribute("data-od-id", `artboard-${board.group}-${index + 1}`);

        card.innerHTML = `
          <div class="artboard-meta">
            <div class="artboard-title-wrap">
              <span class="artboard-index">${String(index + 1).padStart(2, "0")}</span>
              <input class="title-input" value="${escapeHTML(board.title)}" aria-label="${index + 1}번 시안 이름">
              <select class="mini-select screen-select" aria-label="${index + 1}번 화면 선택">
                ${Object.entries(screenLabels).map(([value, label]) =>
                  `<option value="${value}" ${board.screen === value ? "selected" : ""}>${label}</option>`
                ).join("")}
              </select>
              <select class="mini-select variant-select" aria-label="${index + 1}번 스타일 방향 선택">
                ${Object.entries(VARIANTS).map(([value, data]) =>
                  `<option value="${value}" ${board.variant === value ? "selected" : ""}>${data.label}</option>`
                ).join("")}
              </select>
            </div>
            <div class="artboard-actions">
              <button class="action-button duplicate" aria-label="시안 복제">복제</button>
              <button class="action-button inspect" aria-label="미리보기 조작">조작</button>
              <button class="action-button focus" aria-label="시안 크게 보기">확대</button>
              <button class="action-button remove" aria-label="시안 삭제">삭제</button>
            </div>
          </div>

          <div class="artboard-frame">
            <iframe
              src="${SOURCE_FILE}"
              title="${escapeHTML(board.title)} 미리보기"
              sandbox="allow-scripts allow-same-origin"
            ></iframe>
            <button class="artboard-shield" aria-label="${escapeHTML(board.title)} 크게 보기"></button>
            <span class="mode-badge">조작 모드 · Esc로 종료</span>
          </div>

          <div class="direction-caption">
            <strong>${VARIANTS[board.variant].label}</strong>
            <p>${VARIANTS[board.variant].note}</p>
          </div>
        `;

        const frame = card.querySelector(".artboard-frame");
        const iframe = card.querySelector("iframe");
        sizeFrame(frame, iframe);

        iframe.addEventListener("load", () => {
          prepareFrame(iframe, board);
          setTimeout(() => prepareFrame(iframe, board), 120);
        });

        card.querySelector(".title-input").addEventListener("change", event => {
          board.title = event.target.value.trim() || `시안 ${index + 1}`;
          iframe.title = `${board.title} 미리보기`;
          saveBoards();
        });

        card.querySelector(".screen-select").addEventListener("change", event => {
          board.screen = event.target.value;
          saveBoards();
          prepareFrame(iframe, board);
        });

        card.querySelector(".variant-select").addEventListener("change", event => {
          board.variant = event.target.value;
          saveBoards();
          prepareFrame(iframe, board);
          renderBoards();
        });

        card.querySelector(".duplicate").addEventListener("click", () => {
          const boardIndex = boards.findIndex(item => item.id === board.id);
          boards.splice(boardIndex + 1, 0, {
            ...board,
            id: crypto.randomUUID(),
            title: `${board.title} 복사본`
          });
          saveBoards();
          renderBoards();
          toast("시안을 같은 그룹에 복제했습니다.");
        });

        function toggleInspect(force) {
          const next = typeof force === "boolean"
            ? force
            : !frame.classList.contains("inspecting");

          document.querySelectorAll(".artboard-frame.inspecting").forEach(item => {
            if (item !== frame) {
              item.classList.remove("inspecting");
              item.closest(".artboard-card").querySelector(".inspect").textContent = "조작";
            }
          });

          frame.classList.toggle("inspecting", next);
          card.querySelector(".inspect").textContent = next ? "완료" : "조작";
          toast(next
            ? "아트보드 안의 인터랙션을 직접 조작할 수 있습니다."
            : "보드 탐색 모드로 돌아왔습니다.");
        }

        card.querySelector(".inspect").addEventListener("click", () => toggleInspect());
        card.querySelector(".focus").addEventListener("click", () => openFocus(board));
        card.querySelector(".artboard-shield").addEventListener("click", () => openFocus(board));
        card.querySelector(".artboard-shield").addEventListener("dblclick", () => toggleInspect(true));

        card.querySelector(".remove").addEventListener("click", () => {
          boards = boards.filter(item => item.id !== board.id);
          saveBoards();
          renderBoards();
          toast("시안을 보드에서 제거했습니다.");
        });

        return card;
      }

      function renderGroup(group, grid) {
        grid.innerHTML = "";
        const groupBoards = boards.filter(board => board.group === group);

        if (!groupBoards.length) {
          grid.innerHTML = `
            <div class="empty-board">
              <div>
                <strong>이 그룹에 시안이 없습니다</strong>
                <p>상단의 시안 추가를 눌러 새 탐색 방향을 만드세요.</p>
              </div>
            </div>
          `;
          return;
        }

        groupBoards.forEach((board, index) => {
          grid.appendChild(createCard(board, index));
        });
      }

      function renderBoards() {
        renderGroup("flow", flowGrid);
        renderGroup("study", studyGrid);
        applyZoom(zoom);
      }

      function applyZoom(nextZoom) {
        zoom = nextZoom;
        localStorage.setItem("memory-lens-board-zoom", String(zoom));

        document.querySelectorAll(".artboard-frame").forEach(frame => {
          sizeFrame(frame, frame.querySelector("iframe"));
        });

        document.querySelectorAll(".segment").forEach(button => {
          button.classList.toggle("active", Number(button.dataset.zoom) === zoom);
        });
      }

      function fitBoard() {
        const usableWidth = Math.max(760, viewport.clientWidth - 160);
        const next = Math.min(0.4, Math.max(0.2, (usableWidth - 60) / (FRAME_WIDTH * 3)));
        applyZoom(Math.round(next * 100) / 100);
        viewport.scrollTo({ left: 0, top: 0, behavior: "smooth" });
        toast("세 개의 시안이 한 줄에 보이도록 맞췄습니다.");
      }

      function addBoard() {
        const group = boards.some(board => board.group === "study") ? "study" : "flow";
        const groupBoards = boards.filter(board => board.group === group);
        const source = groupBoards[groupBoards.length - 1];

        boards.push({
          id: crypto.randomUUID(),
          group,
          title: source ? `${source.title} 새 시안` : "새 Home 시안",
          screen: source?.screen || "home",
          variant: source?.variant || "orbit"
        });

        saveBoards();
        renderBoards();
        toast("Home 방향 시안 그룹에 새 아트보드를 추가했습니다.");
      }

      function openFocus(board) {
        const layer = document.getElementById("focusLayer");
        const viewportElement = document.getElementById("focusViewport");
        document.getElementById("focusTitle").textContent = board.title;

        viewportElement.innerHTML = `
          <iframe
            src="${SOURCE_FILE}"
            title="${escapeHTML(board.title)} 포커스 미리보기"
            sandbox="allow-scripts allow-same-origin"
          ></iframe>
        `;

        const iframe = viewportElement.querySelector("iframe");
        iframe.addEventListener("load", () => {
          prepareFrame(iframe, board);
          const availableWidth = viewportElement.clientWidth;
          const availableHeight = viewportElement.clientHeight;
          const scale = Math.min(availableWidth / FRAME_WIDTH, availableHeight / FRAME_HEIGHT);
          iframe.style.transform = `scale(${scale})`;
          iframe.style.width = `${FRAME_WIDTH}px`;
          iframe.style.height = `${FRAME_HEIGHT}px`;
          viewportElement.style.overflow = "hidden";
        });

        layer.classList.add("open");
        layer.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
        setTimeout(() => document.getElementById("closeFocus").focus(), 20);
      }

      function closeFocus() {
        const layer = document.getElementById("focusLayer");
        layer.classList.remove("open");
        layer.setAttribute("aria-hidden", "true");
        document.getElementById("focusViewport").innerHTML = "";
        document.body.style.overflow = "";
      }

      document.querySelectorAll(".segment").forEach(button => {
        button.addEventListener("click", () => applyZoom(Number(button.dataset.zoom)));
      });

      document.getElementById("addArtboard").addEventListener("click", addBoard);
      document.getElementById("fitBoard").addEventListener("click", fitBoard);

      document.getElementById("resetBoard").addEventListener("click", () => {
        boards = DEFAULT_BOARDS.map(board => ({ ...board, id: crypto.randomUUID() }));
        zoom = 0.3;
        saveBoards();
        renderBoards();
        toast("코어 플로우와 3개 방향 시안으로 되돌렸습니다.");
      });

      document.getElementById("closeFocus").addEventListener("click", closeFocus);

      document.getElementById("focusLayer").addEventListener("click", event => {
        if (event.target.id === "focusLayer") closeFocus();
      });

      document.addEventListener("keydown", event => {
        if (event.key !== "Escape") return;

        if (document.getElementById("focusLayer").classList.contains("open")) {
          closeFocus();
          return;
        }

        document.querySelectorAll(".artboard-frame.inspecting").forEach(frame => {
          frame.classList.remove("inspecting");
          frame.closest(".artboard-card").querySelector(".inspect").textContent = "조작";
        });
      });

      let panState = null;

      viewport.addEventListener("pointerdown", event => {
        if (event.button !== 1 && !(event.button === 0 && event.altKey)) return;

        panState = {
          x: event.clientX,
          y: event.clientY,
          left: viewport.scrollLeft,
          top: viewport.scrollTop
        };

        viewport.classList.add("is-panning");
        viewport.setPointerCapture(event.pointerId);
      });

      viewport.addEventListener("pointermove", event => {
        if (!panState) return;
        viewport.scrollLeft = panState.left - (event.clientX - panState.x);
        viewport.scrollTop = panState.top - (event.clientY - panState.y);
      });

      viewport.addEventListener("pointerup", () => {
        panState = null;
        viewport.classList.remove("is-panning");
      });

      renderBoards();
    })();
  </script>
</body>
</html>
</artifact>

content.text:
스케치보드를 코어 플로우와 Home 방향 시안을 동시에 비교하는 크리에이티브 캔버스로 개편했습니다.

<artifact identifier="memory-lens-sketchboard" type="text/html" title="Memory Lens 크리에이티브 스케치보드">
<!doctype html>
<html lang="ko">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Memory Lens — 크리에이티브 스케치보드</title>
  <style>
    :root {
      --bg: oklch(0.925 0.008 255);
      --surface: oklch(0.985 0.004 255);
      --fg: oklch(0.19 0.022 258);
      --muted: oklch(0.49 0.02 258);
      --border: oklch(0.79 0.014 255);
      --accent: oklch(0.55 0.19 255);
      --board: oklch(0.875 0.011 255);
      --danger: oklch(0.56 0.16 28);
      --body: "Pretendard Variable", "Pretendard", "Apple SD Gothic Neo", "Segoe UI Variable", sans-serif;
      --mono: "SFMono-Regular", "Cascadia Code", Consolas, monospace;
      --ease: cubic-bezier(0.23, 1, 0.32, 1);
    }

    * { box-sizing: border-box; }

    html,
    body {
      width: 100%;
      min-height: 100%;
      margin: 0;
      overflow: hidden;
      background: var(--board);
      color: var(--fg);
      font-family: var(--body);
    }

    button,
    select,
    input { font: inherit; }

    button {
      color: inherit;
      cursor: pointer;
    }

    button:focus-visible,
    select:focus-visible,
    input:focus-visible {
      outline: 3px solid oklch(0.7 0.15 255);
      outline-offset: 2px;
    }

    .board-shell {
      height: 100vh;
      display: grid;
      grid-template-rows: 66px minmax(0, 1fr);
    }

    .toolbar {
      position: relative;
      z-index: 30;
      min-width: 0;
      padding: 0 18px;
      border-bottom: 1px solid var(--border);
      background: oklch(0.975 0.006 255 / 0.94);
      box-shadow: 0 4px 18px oklch(0.2 0.02 258 / 0.07);
      backdrop-filter: blur(18px);
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .brand {
      flex: 0 0 auto;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .brand-mark {
      width: 31px;
      height: 31px;
      border: 1px solid var(--fg);
      border-radius: 50%;
      display: grid;
      place-items: center;
      font-size: 9px;
      font-weight: 780;
      letter-spacing: -0.05em;
    }

    .brand-copy strong {
      display: block;
      margin-bottom: 1px;
      font-size: 13px;
      letter-spacing: -0.025em;
    }

    .brand-copy span {
      display: block;
      color: var(--muted);
      font: 9px var(--mono);
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    .toolbar-divider {
      width: 1px;
      height: 28px;
      background: var(--border);
    }

    .toolbar-section {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .toolbar-section.push { margin-left: auto; }

    .toolbar-label {
      margin-right: 2px;
      color: var(--muted);
      font-size: 10px;
    }

    .tool-button {
      min-height: 38px;
      padding: 0 12px;
      border: 1px solid transparent;
      border-radius: 8px;
      background: transparent;
      font-size: 11px;
      transition:
        background 150ms var(--ease),
        border-color 150ms var(--ease),
        transform 150ms var(--ease);
    }

    .tool-button:hover {
      border-color: var(--border);
      background: var(--surface);
    }

    .tool-button.primary {
      border-color: var(--fg);
      background: var(--fg);
      color: white;
      font-weight: 680;
    }

    .tool-button.primary:hover {
      background: oklch(0.28 0.025 258);
      transform: translateY(-1px);
    }

    .segmented {
      min-height: 38px;
      padding: 3px;
      border: 1px solid var(--border);
      border-radius: 9px;
      background: var(--surface);
      display: flex;
      align-items: center;
    }

    .segment {
      min-width: 42px;
      min-height: 30px;
      padding: 0 9px;
      border: 0;
      border-radius: 6px;
      background: transparent;
      color: var(--muted);
      font-size: 10px;
    }

    .segment:hover {
      background: var(--bg);
      color: var(--fg);
    }

    .segment.active {
      background: var(--fg);
      color: white;
    }

    .board-viewport {
      position: relative;
      min-width: 0;
      min-height: 0;
      overflow: auto;
      cursor: grab;
    }

    .board-viewport.is-panning { cursor: grabbing; }

    .board-canvas {
      position: relative;
      min-width: 100%;
      min-height: 100%;
      padding: 64px;
      background-color: var(--board);
      background-image:
        linear-gradient(oklch(0.63 0.01 255 / 0.18) 1px, transparent 1px),
        linear-gradient(90deg, oklch(0.63 0.01 255 / 0.18) 1px, transparent 1px),
        radial-gradient(circle, oklch(0.61 0.01 255 / 0.42) 1px, transparent 1px);
      background-size: 80px 80px, 80px 80px, 16px 16px;
    }

    .board-header {
      max-width: 760px;
      margin-bottom: 54px;
    }

    .board-eyebrow {
      margin-bottom: 10px;
      color: var(--muted);
      font: 10px var(--mono);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .board-header h1 {
      max-width: 680px;
      margin: 0 0 10px;
      font-size: 31px;
      line-height: 1.14;
      letter-spacing: -0.05em;
    }

    .board-header p {
      max-width: 650px;
      margin: 0;
      color: var(--muted);
      font-size: 13px;
      line-height: 1.7;
    }

    .board-section {
      width: max-content;
      min-width: 100%;
      margin-bottom: 72px;
    }

    .section-heading {
      margin-bottom: 20px;
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
    }

    .section-heading-main {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .section-number {
      width: 27px;
      height: 27px;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: var(--surface);
      display: grid;
      place-items: center;
      color: var(--muted);
      font: 9px var(--mono);
    }

    .section-heading h2 {
      margin: 0 0 3px;
      font-size: 17px;
      letter-spacing: -0.035em;
    }

    .section-heading p {
      margin: 0;
      color: var(--muted);
      font-size: 11px;
    }

    .section-note {
      max-width: 320px;
      color: var(--muted);
      font: 9px/1.5 var(--mono);
      text-align: right;
    }

    .artboard-grid {
      display: flex;
      align-items: flex-start;
      gap: 30px;
      width: max-content;
      min-width: 100%;
      flex-wrap: wrap;
    }

    .artboard-card {
      position: relative;
      flex: 0 0 auto;
      min-width: 0;
    }

    .artboard-meta {
      min-height: 47px;
      margin-bottom: 10px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .artboard-title-wrap {
      min-width: 0;
      display: flex;
      align-items: center;
      gap: 7px;
    }

    .artboard-index {
      width: 24px;
      height: 24px;
      flex: 0 0 auto;
      border: 1px solid var(--border);
      border-radius: 50%;
      background: var(--surface);
      display: grid;
      place-items: center;
      color: var(--muted);
      font: 8px var(--mono);
    }

    .title-input {
      width: 156px;
      min-height: 34px;
      padding: 0 8px;
      border: 1px solid transparent;
      border-radius: 6px;
      background: transparent;
      color: var(--fg);
      font-size: 12px;
      font-weight: 680;
      letter-spacing: -0.025em;
    }

    .title-input:hover,
    .title-input:focus {
      border-color: var(--border);
      background: var(--surface);
    }

    .mini-select {
      min-height: 34px;
      padding: 0 27px 0 9px;
      border: 1px solid var(--border);
      border-radius: 7px;
      background: var(--surface);
      color: var(--fg);
      font-size: 10px;
    }

    .artboard-actions {
      display: flex;
      gap: 3px;
    }

    .action-button {
      min-width: 34px;
      min-height: 34px;
      padding: 0 8px;
      border: 1px solid transparent;
      border-radius: 7px;
      background: transparent;
      color: var(--muted);
      font-size: 9px;
    }

    .action-button:hover {
      border-color: var(--border);
      background: var(--surface);
      color: var(--fg);
    }

    .action-button.remove:hover {
      border-color: oklch(0.76 0.08 28);
      background: oklch(0.95 0.025 28);
      color: var(--danger);
    }

    .artboard-frame {
      position: relative;
      border: 1px solid oklch(0.59 0.01 255);
      border-radius: 5px;
      background: white;
      box-shadow:
        0 1px 2px oklch(0.2 0.02 258 / 0.16),
        0 18px 48px oklch(0.2 0.025 258 / 0.13);
      overflow: hidden;
      transition:
        box-shadow 180ms var(--ease),
        transform 180ms var(--ease);
    }

    .artboard-card:hover .artboard-frame {
      box-shadow:
        0 1px 2px oklch(0.2 0.02 258 / 0.18),
        0 24px 68px oklch(0.2 0.025 258 / 0.18);
      transform: translateY(-2px);
    }

    .artboard-frame iframe {
      position: absolute;
      inset: 0 auto auto 0;
      width: 1440px;
      height: 900px;
      border: 0;
      background: white;
      transform-origin: top left;
      pointer-events: none;
    }

    .artboard-frame.inspecting iframe { pointer-events: auto; }

    .artboard-shield {
      position: absolute;
      inset: 0;
      z-index: 2;
      border: 0;
      background: transparent;
      cursor: zoom-in;
    }

    .artboard-frame.inspecting .artboard-shield { display: none; }

    .mode-badge {
      position: absolute;
      right: 9px;
      bottom: 9px;
      z-index: 3;
      min-height: 28px;
      padding: 0 9px;
      border: 1px solid oklch(1 0 0 / 0.2);
      border-radius: 7px;
      background: oklch(0.18 0.025 258 / 0.88);
      color: white;
      display: none;
      align-items: center;
      font-size: 9px;
      backdrop-filter: blur(10px);
    }

    .artboard-frame.inspecting .mode-badge { display: flex; }

    .direction-caption {
      max-width: 430px;
      min-height: 60px;
      padding-top: 13px;
      display: grid;
      grid-template-columns: 76px 1fr;
      gap: 12px;
    }

    .direction-caption strong {
      color: var(--muted);
      font: 9px var(--mono);
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    .direction-caption p {
      margin: 0;
      color: var(--muted);
      font-size: 10px;
      line-height: 1.55;
    }

    .focus-layer {
      position: fixed;
      inset: 0;
      z-index: 40;
      padding: 24px;
      background: oklch(0.14 0.02 258 / 0.86);
      display: grid;
      place-items: center;
      opacity: 0;
      visibility: hidden;
      transition: opacity 150ms var(--ease), visibility 150ms;
    }

    .focus-layer.open {
      opacity: 1;
      visibility: visible;
    }

    .focus-panel {
      width: min(94vw, 1280px);
      height: min(88vh, 800px);
      border: 1px solid oklch(1 0 0 / 0.2);
      border-radius: 12px;
      background: white;
      box-shadow: 0 34px 100px oklch(0.05 0.02 258 / 0.38);
      overflow: hidden;
      transform: scale(0.98);
      transition: transform 190ms var(--ease);
    }

    .focus-layer.open .focus-panel { transform: scale(1); }

    .focus-toolbar {
      height: 48px;
      padding: 0 13px;
      border-bottom: 1px solid var(--border);
      background: var(--surface);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .focus-toolbar strong {
      font-size: 12px;
      letter-spacing: -0.02em;
    }

    .focus-close {
      min-width: 40px;
      min-height: 34px;
      border: 1px solid var(--border);
      border-radius: 7px;
      background: transparent;
      font-size: 11px;
    }

    .focus-close:hover { background: var(--bg); }

    .focus-viewport {
      width: 100%;
      height: calc(100% - 48px);
      overflow: auto;
      background: var(--bg);
    }

    .focus-viewport iframe {
      width: 1440px;
      height: 900px;
      border: 0;
      background: white;
      transform-origin: top left;
    }

    .empty-board {
      width: 430px;
      min-height: 260px;
      padding: 38px;
      border: 1px dashed oklch(0.62 0.02 255);
      border-radius: 10px;
      background: oklch(0.94 0.008 255 / 0.5);
      display: grid;
      place-items: center;
      text-align: center;
    }

    .empty-board strong {
      display: block;
      margin-bottom: 8px;
      font-size: 14px;
    }

    .empty-board p {
      max-width: 300px;
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 11px;
      line-height: 1.6;
    }

    .toast {
      position: fixed;
      left: 50%;
      bottom: 24px;
      z-index: 60;
      min-width: 240px;
      padding: 12px 16px;
      border-radius: 9px;
      background: var(--fg);
      color: white;
      text-align: center;
      font-size: 11px;
      box-shadow: 0 16px 44px oklch(0.2 0.03 258 / 0.2);
      opacity: 0;
      transform: translate(-50%, 10px);
      pointer-events: none;
      transition: opacity 160ms var(--ease), transform 160ms var(--ease);
    }

    .toast.show {
      opacity: 1;
      transform: translate(-50%, 0);
    }

    @media (max-width: 920px) {
      .brand-copy span,
      .toolbar-divider,
      .toolbar-label,
      .section-note { display: none; }

      .toolbar {
        gap: 7px;
        padding-inline: 10px;
      }

      .toolbar-section.push { margin-left: auto; }
      .board-canvas { padding: 38px 24px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <div class="board-shell">
    <header class="toolbar" data-od-id="sketchboard-toolbar">
      <div class="brand">
        <div class="brand-mark">ML</div>
        <div class="brand-copy">
          <strong>Memory Lens</strong>
          <span>Creative board</span>
        </div>
      </div>

      <div class="toolbar-divider"></div>

      <div class="toolbar-section">
        <span class="toolbar-label">배율</span>
        <div class="segmented" role="group" aria-label="아트보드 배율">
          <button class="segment" data-zoom="0.24">24%</button>
          <button class="segment active" data-zoom="0.3">30%</button>
          <button class="segment" data-zoom="0.4">40%</button>
          <button class="segment" data-zoom="0.52">52%</button>
        </div>
      </div>

      <div class="toolbar-section push">
        <button class="tool-button" id="fitBoard" data-od-id="fit-board">전체 맞춤</button>
        <button class="tool-button" id="resetBoard" data-od-id="reset-board">기본 보드</button>
        <button class="tool-button primary" id="addArtboard" data-od-id="add-artboard">시안 추가</button>
      </div>
    </header>

    <div class="board-viewport" id="boardViewport">
      <main class="board-canvas" data-od-id="sketchboard-canvas">
        <header class="board-header">
          <div class="board-eyebrow">Memory Lens · Desktop product study</div>
          <h1 data-od-id="board-heading">기억을 관리하는 화면이 아니라, AI의 이해를 검토하는 경험</h1>
          <p>코어 플로우와 Home의 시각 방향을 한 캔버스에서 비교합니다. 화면을 복제해 탐색하고, 포커스 모드에서 실제 인터랙션을 확인하세요.</p>
        </header>

        <section class="board-section" data-od-id="core-flow-section">
          <div class="section-heading">
            <div class="section-heading-main">
              <span class="section-number">01</span>
              <div>
                <h2 data-od-id="core-flow-heading">코어 플로우</h2>
                <p>변화 확인 → 자기 모델 탐색 → AI별 공유 범위 제어</p>
              </div>
            </div>
            <span class="section-note">제품 구조와 작업 밀도를 비교하는 화면군</span>
          </div>
          <div class="artboard-grid" id="flowGrid" data-od-id="core-flow-grid"></div>
        </section>

        <section class="board-section" data-od-id="direction-study-section">
          <div class="section-heading">
            <div class="section-heading-main">
              <span class="section-number">02</span>
              <div>
                <h2 data-od-id="direction-study-heading">Home 방향 시안</h2>
                <p>동일한 기억 리포트 경험을 서로 다른 정보 태도로 비교</p>
              </div>
            </div>
            <span class="section-note">장식이 아니라 이해 속도와 신뢰감의 차이를 평가</span>
          </div>
          <div class="artboard-grid" id="studyGrid" data-od-id="direction-study-grid"></div>
        </section>
      </main>
    </div>
  </div>

  <div class="focus-layer" id="focusLayer" aria-hidden="true">
    <section class="focus-panel" role="dialog" aria-modal="true" aria-labelledby="focusTitle">
      <header class="focus-toolbar">
        <strong id="focusTitle">시안 포커스</strong>
        <button class="focus-close" id="closeFocus" aria-label="포커스 모드 닫기">닫기</button>
      </header>
      <div class="focus-viewport" id="focusViewport"></div>
    </section>
  </div>

  <div class="toast" id="toast" role="status" aria-live="polite"></div>

  <script>
    (() => {
      const SOURCE_FILE = "memory-lens-desktop.html";
      const FRAME_WIDTH = 1440;
      const FRAME_HEIGHT = 900;

      const VARIANTS = {
        orbit: {
          label: "Orbit Core",
          note: "기억 조각의 움직임과 중심 코어를 전면에 둔 현재 방향. 가장 강한 제품 정체성을 제공합니다."
        },
        quiet: {
          label: "Quiet Intelligence",
          note: "밝은 배경과 낮은 대비의 오빗으로 신뢰와 설명 가능성을 우선합니다."
        },
        signal: {
          label: "Signal Grid",
          note: "리포트 수치와 변화 신호를 더 빠르게 스캔하도록 밀도를 높인 운영형 방향입니다."
        }
      };

      const DEFAULT_BOARDS = [
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Home · What changed",
          screen: "home",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Me · What AI thinks",
          screen: "me",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "flow",
          title: "Control · Who can know",
          screen: "control",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "A · Orbit Core",
          screen: "home",
          variant: "orbit"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "B · Quiet Intelligence",
          screen: "home",
          variant: "quiet"
        },
        {
          id: crypto.randomUUID(),
          group: "study",
          title: "C · Signal Grid",
          screen: "home",
          variant: "signal"
        }
      ];

      const screenLabels = {
        home: "Home",
        me: "Me",
        control: "Control"
      };

      let zoom = Number(localStorage.getItem("memory-lens-board-zoom")) || 0.3;
      let boards = loadBoards();
      let toastTimer;

      const viewport = document.getElementById("boardViewport");
      const flowGrid = document.getElementById("flowGrid");
      const studyGrid = document.getElementById("studyGrid");

      function loadBoards() {
        try {
          const stored = JSON.parse(localStorage.getItem("memory-lens-creative-board"));
          if (Array.isArray(stored) && stored.length) return stored;
        } catch (_) {}
        return DEFAULT_BOARDS;
      }

      function saveBoards() {
        localStorage.setItem("memory-lens-creative-board", JSON.stringify(boards));
      }

      function escapeHTML(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function toast(message) {
        const element = document.getElementById("toast");
        element.textContent = message;
        element.classList.add("show");
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => element.classList.remove("show"), 1800);
      }

      function sizeFrame(frame, iframe) {
        frame.style.width = `${FRAME_WIDTH * zoom}px`;
        frame.style.height = `${FRAME_HEIGHT * zoom}px`;
        iframe.style.transform = `scale(${zoom})`;
      }

      function variantCSS(variant) {
        if (variant === "quiet") {
          return `
            .memory-hero {
              background: oklch(0.955 0.012 255) !important;
              color: oklch(0.19 0.022 258) !important;
              box-shadow: 0 18px 50px oklch(0.2 0.02 258 / 0.1) !important;
            }
            .memory-hero::before { opacity: .07 !important; }
            .hero-copy > p { color: oklch(0.48 0.025 258) !important; }
            .hero-eyebrow { color: oklch(0.46 0.12 255) !important; }
            .hero-primary {
              border-color: oklch(0.19 0.022 258) !important;
              background: oklch(0.19 0.022 258) !important;
              color: white !important;
            }
            .hero-secondary {
              border-color: oklch(0.72 0.02 255) !important;
              background: oklch(1 0 0 / .6) !important;
              color: oklch(0.19 0.022 258) !important;
            }
            .orbit-ring { border-color: oklch(0.52 0.08 255 / .18) !important; }
            .orbit-stage { filter: saturate(.72); }
            .memory-chip {
              border-color: oklch(0.76 0.025 255) !important;
              background: oklch(0.99 0.004 255 / .82) !important;
              color: oklch(0.25 0.025 258) !important;
              box-shadow: 0 8px 24px oklch(0.2 0.02 258 / .09) !important;
            }
            .hero-report-strip {
              border-color: oklch(0.77 0.018 255) !important;
              background: oklch(0.99 0.004 255 / .82) !important;
              color: oklch(0.19 0.022 258) !important;
            }
            .report-intro span, .report-stat span {
              color: oklch(0.5 0.02 258) !important;
            }
            .report-stat { border-color: oklch(0.82 0.015 255) !important; }
          `;
        }

        if (variant === "signal") {
          return `
            .memory-hero { min-height: 560px !important; }
            .hero-copy {
              width: 61% !important;
              min-height: 460px !important;
              padding-top: 42px !important;
            }
            .hero-copy h1 {
              max-width: 760px !important;
              font-size: 62px !important;
            }
            .orbit-stage {
              right: -130px !important;
              width: 48% !important;
              opacity: .68 !important;
              transform: scale(.83) !important;
            }
            .hero-report-strip {
              left: 0 !important;
              right: 0 !important;
              bottom: 0 !important;
              min-height: 82px !important;
              border-left: 0 !important;
              border-right: 0 !important;
              border-bottom: 0 !important;
              border-radius: 0 !important;
            }
            .summary-grid {
              grid-template-columns: repeat(4, 1fr) !important;
              margin-top: -8px !important;
            }
            .summary-item { min-height: 108px !important; }
          `;
        }

        return "";
      }

      function prepareFrame(iframe, board) {
        try {
          const doc = iframe.contentDocument;
          if (!doc) return;

          const screenButton = doc.querySelector(`.nav-button[data-screen="${board.screen}"]`);
          if (screenButton) screenButton.click();

          const oldStyle = doc.getElementById("board-variant-style");
          if (oldStyle) oldStyle.remove();

          const style = doc.createElement("style");
          style.id = "board-variant-style";
          style.textContent = variantCSS(board.variant);
          doc.head.appendChild(style);
          doc.body.dataset.boardVariant = board.variant;
        } catch (_) {
          toast("미리보기는 프로젝트 서버에서 열어주세요.");
        }
      }

      function createCard(board, index) {
        const card = document.createElement("article");
        card.className = "artboard-card";
        card.dataset.boardId = board.id;
        card.setAttribute("data-od-id", `artboard-${board.group}-${index + 1}`);

        card.innerHTML = `
          <div class="artboard-meta">
            <div class="artboard-title-wrap">
              <span class="artboard-index">${String(index + 1).padStart(2, "0")}</span>
              <input class="title-input" value="${escapeHTML(board.title)}" aria-label="${index + 1}번 시안 이름">
              <select class="mini-select screen-select" aria-label="${index + 1}번 화면 선택">
                ${Object.entries(screenLabels).map(([value, label]) =>
                  `<option value="${value}" ${board.screen === value ? "selected" : ""}>${label}</option>`
                ).join("")}
              </select>
              <select class="mini-select variant-select" aria-label="${index + 1}번 스타일 방향 선택">
                ${Object.entries(VARIANTS).map(([value, data]) =>
                  `<option value="${value}" ${board.variant === value ? "selected" : ""}>${data.label}</option>`
                ).join("")}
              </select>
            </div>
            <div class="artboard-actions">
              <button class="action-button duplicate" aria-label="시안 복제">복제</button>
              <button class="action-button inspect" aria-label="미리보기 조작">조작</button>
              <button class="action-button focus" aria-label="시안 크게 보기">확대</button>
              <button class="action-button remove" aria-label="시안 삭제">삭제</button>
            </div>
          </div>

          <div class="artboard-frame">
            <iframe
              src="${SOURCE_FILE}"
              title="${escapeHTML(board.title)} 미리보기"
              sandbox="allow-scripts allow-same-origin"
            ></iframe>
            <button class="artboard-shield" aria-label="${escapeHTML(board.title)} 크게 보기"></button>
            <span class="mode-badge">조작 모드 · Esc로 종료</span>
          </div>

          <div class="direction-caption">
            <strong>${VARIANTS[board.variant].label}</strong>
            <p>${VARIANTS[board.variant].note}</p>
          </div>
        `;

        const frame = card.querySelector(".artboard-frame");
        const iframe = card.querySelector("iframe");
        sizeFrame(frame, iframe);

        iframe.addEventListener("load", () => {
          prepareFrame(iframe, board);
          setTimeout(() => prepareFrame(iframe, board), 120);
        });

        card.querySelector(".title-input").addEventListener("change", event => {
          board.title = event.target.value.trim() || `시안 ${index + 1}`;
          iframe.title = `${board.title} 미리보기`;
          saveBoards();
        });

        card.querySelector(".screen-select").addEventListener("change", event => {
          board.screen = event.target.value;
          saveBoards();
          prepareFrame(iframe, board);
        });

        card.querySelector(".variant-select").addEventListener("change", event => {
          board.variant = event.target.value;
